import React, { useState, useEffect, useCallback } from 'react';
import {
  FolderOpen,
  Search,
  Settings,
  LogOut,
  ChevronLeft,
  Plus,
} from 'lucide-react';
import { useAuth } from '../../context/AuthContext.js';
import { api } from '../../lib/api.js';
import { cn } from '../../lib/utils.js';
import { ThemeToggle } from '../common/ThemeToggle.js';

import type { Category, Project } from '../../types/project.js';

export interface SidebarProps {
  currentView?: string;
  currentProjectId?: string;
  onNavigate?: (view: string, projectId?: string) => void;
  onOpenCommandPalette?: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({
  currentView = 'dashboard',
  currentProjectId,
  onNavigate,
  onOpenCommandPalette,
}) => {
  const { user, logout } = useAuth();
  const [projects, setProjects] = useState<any[]>([]);
  const [categories, setCategories] = useState<any[]>([]);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);

  const handleNav = (view: string, projectId?: string) => {
    onNavigate?.(view, projectId);
    setIsDrawerOpen(false);
  };

  // Fetch all projects for drawer
  const fetchProjects = useCallback(async () => {
    try {
      const res = await api.get<{ projects: any[] }>('/api/projects');
      setProjects(res.projects || []);
    } catch {
      // non-blocking
    }
  }, []);

  const fetchCategories = useCallback(async () => {
    try {
      const res = await api.get<{ categories: any[] }>('/api/categories');
      setCategories(res.categories || []);
    } catch {}
  }, []);

  useEffect(() => {
    fetchProjects();
    fetchCategories();
  }, [fetchProjects, fetchCategories]);

  // Right-click context menu on project items
  const [contextMenu, setContextMenu] = useState<{ project: any; x: number; y: number } | null>(null);

  useEffect(() => {
    const close = () => setContextMenu(null);
    window.addEventListener('click', close);
    return () => window.removeEventListener('click', close);
  }, []);

  const handleDeleteProject = async (projectId: string, title: string) => {
    if (!window.confirm(`Supprimer "${title}" ?`)) return;
    try {
      await api.delete(`/api/projects/${projectId}`);
      fetchProjects();
    } catch {}
  };

  const handleRenameProject = async (projectId: string, currentTitle: string) => {
    const newTitle = prompt('Nouveau nom du projet :', currentTitle);
    if (newTitle && newTitle.trim() && newTitle.trim() !== currentTitle) {
      try {
        await api.patch(`/api/projects/${projectId}`, { title: newTitle.trim() });
        fetchProjects();
      } catch {}
    }
  };

  const handleUpdateCategory = async (projectId: string, catId: string | null) => {
    try {
      await api.patch(`/api/projects/${projectId}`, { categoryId: catId });
      fetchProjects();
    } catch {}
  };

  const handleUpdateStatus = async (projectId: string, status: string) => {
    try {
      await api.patch(`/api/projects/${projectId}`, { status });
      fetchProjects();
    } catch {}
  };

  const handleUpdateParentProject = async (projectId: string, parentId: string | null) => {
    try {
      await api.patch(`/api/projects/${projectId}`, { parentId });
      fetchProjects();
    } catch {}
  };

  const getGroupedProjects = () => {
    const grouped: Record<string, { category: Category | null; rootProjects: Project[] }> = {};

    // Initialize categories
    categories.forEach((cat) => {
      grouped[cat.id] = { category: cat, rootProjects: [] };
    });
    // Add default group for uncategorized
    grouped['uncategorized'] = { category: null, rootProjects: [] };

    // Separate root and sub-projects
    const rootProjects = (projects as Project[]).filter((p) => !p.parentId);
    const subProjects = (projects as Project[]).filter((p) => p.parentId);

    // Map root projects to categories
    rootProjects.forEach((p) => {
      const catId = p.categoryId || 'uncategorized';
      if (grouped[catId]) {
        grouped[catId].rootProjects.push(p);
      }
    });

    return { grouped, subProjects };
  };

  return (
    <>
      {/* FIXED 64px RAIL SIDEBAR */}
      <aside
        className="fixed inset-y-0 left-0 z-40 flex flex-col w-16 bg-background-surface border-r border-border select-none"
        data-testid="app-sidebar"
      >
        {/* Logo */}
        <div className="flex items-center justify-center h-16 border-b border-border shrink-0">
          <div
            onClick={() => handleNav('dashboard')}
            className="w-10 h-10 rounded-xl bg-foreground flex items-center justify-center text-background font-bold text-base tracking-wider cursor-pointer hover:opacity-80 transition-opacity"
            title="Ohara"
          >
            O
          </div>
        </div>

        {/* Navigation */}
        <nav className="flex-1 px-2 py-4 space-y-2 flex flex-col items-center">
          <button
            type="button"
            onClick={() => setIsDrawerOpen((prev) => !prev)}
            title="Projets"
            className={cn(
              'w-10 h-10 flex items-center justify-center rounded-xl transition-colors cursor-pointer',
              currentView === 'editor' || isDrawerOpen
                ? 'bg-foreground/10 text-foreground'
                : 'text-foreground-muted hover:text-foreground hover:bg-background-hover'
            )}
          >
            <FolderOpen className="w-5 h-5" />
          </button>

          <button
            type="button"
            onClick={onOpenCommandPalette}
            title="Rechercher (Ctrl+K)"
            className="w-10 h-10 flex items-center justify-center rounded-xl text-foreground-muted hover:text-foreground hover:bg-background-hover transition-colors cursor-pointer"
          >
            <Search className="w-5 h-5" />
          </button>

          <button
            type="button"
            onClick={() => handleNav('categories')}
            title="Paramètres"
            className={cn(
              'w-10 h-10 flex items-center justify-center rounded-xl transition-colors cursor-pointer',
              currentView === 'categories' || currentView === 'tags'
                ? 'bg-foreground/10 text-foreground'
                : 'text-foreground-muted hover:text-foreground hover:bg-background-hover'
            )}
          >
            <Settings className="w-5 h-5" />
          </button>
        </nav>

        {/* Bottom: Theme + Logout */}
        <div className="p-2 border-t border-border flex flex-col gap-2 items-center shrink-0">
          <ThemeToggle />
          {user && (
            <button
              type="button"
              onClick={logout}
              title="Déconnexion"
              className="w-10 h-10 flex items-center justify-center rounded-xl text-foreground-muted hover:text-red-400 hover:bg-background-hover transition-colors cursor-pointer"
            >
              <LogOut className="w-4 h-4" />
            </button>
          )}
        </div>
      </aside>

      {/* PROJECTS DRAWER */}
      {isDrawerOpen && (
        <div
          className="fixed inset-0 z-30"
          onClick={() => setIsDrawerOpen(false)}
        >
          <div
            className="fixed inset-y-0 left-16 z-30 w-72 bg-background-surface border-r border-border flex flex-col"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Drawer header */}
            <div className="flex items-center justify-between h-14 px-4 border-b border-border shrink-0">
              <span className="text-xs font-semibold text-foreground-muted uppercase tracking-wider">
                Projets
              </span>
              <div className="flex items-center gap-1">
                <button
                  onClick={() => {
                    handleNav('projects');
                  }}
                  className="p-1.5 rounded-lg text-foreground-muted hover:text-foreground hover:bg-background-hover transition-colors cursor-pointer"
                  title="Nouveau projet"
                >
                  <Plus className="w-4 h-4" />
                </button>
                <button
                  onClick={() => setIsDrawerOpen(false)}
                  className="p-1.5 rounded-lg text-foreground-muted hover:text-foreground hover:bg-background-hover transition-colors cursor-pointer"
                  title="Fermer"
                >
                  <ChevronLeft className="w-4 h-4" />
                </button>
              </div>
            </div>

            {/* Project list */}
            <div className="flex-1 overflow-y-auto py-2 px-2 space-y-1">
              {projects.length === 0 ? (
                <p className="text-xs text-foreground-muted px-4 py-8 text-center">
                  Aucun projet
                </p>
              ) : (() => {
                const rootProjects = projects.filter((p) => !p.parentId);
                const subProjects = projects.filter((p) => p.parentId);
                return rootProjects.map((proj) => {
                  const subs = subProjects.filter((sp) => sp.parentId === proj.id);
                  return (
                    <div key={proj.id} className="mb-1">
                      {/* Projet principal */}
                      <button
                        type="button"
                        onClick={() => handleNav('editor', proj.id)}
                        onContextMenu={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                          setContextMenu({ project: proj, x: e.clientX, y: e.clientY });
                        }}
                        className={cn(
                          'w-full text-left px-2.5 py-1.5 text-xs rounded-lg flex items-center gap-2 hover:bg-foreground/[0.04] transition-colors cursor-pointer',
                          currentView === 'editor' && currentProjectId === proj.id
                            ? 'bg-foreground/[0.06] text-foreground font-semibold'
                            : 'text-foreground-muted hover:text-foreground'
                        )}
                      >
                        <span
                          className="w-1.5 h-1.5 rounded-full shrink-0"
                          style={{ backgroundColor: proj.category?.color || '#555' }}
                        />
                        <span className="truncate flex-1 font-medium">{proj.title}</span>
                      </button>

                      {/* Sous-projets */}
                      {subs.length > 0 && (
                        <div className="ml-4 pl-2.5 border-l border-foreground/10">
                          {subs.map((sub) => (
                            <button
                              key={sub.id}
                              type="button"
                              onClick={() => handleNav('editor', sub.id)}
                              onContextMenu={(e) => {
                                e.preventDefault();
                                e.stopPropagation();
                                setContextMenu({ project: sub, x: e.clientX, y: e.clientY });
                              }}
                              className={cn(
                                'w-full text-left px-2 py-1 text-[11px] rounded-lg flex items-center gap-1.5 hover:bg-foreground/[0.04] transition-colors cursor-pointer',
                                currentView === 'editor' && currentProjectId === sub.id
                                  ? 'bg-foreground/[0.06] text-foreground font-medium'
                                  : 'text-foreground-subtle hover:text-foreground-muted'
                              )}
                            >
                              <span className="text-foreground/20 text-[9px] select-none shrink-0">└</span>
                              <span className="truncate flex-1">{sub.title}</span>
                            </button>
                          ))}
                        </div>
                      )}
                    </div>
                  );
                });
              })()}
            </div>
          </div>
        </div>
      )}

      {/* Context menu for projects */}
      {contextMenu && (
        <div
          className="fixed z-50 w-48 bg-background-surface border border-border rounded-xl p-1 shadow-lg flex flex-col gap-0.5"
          style={{ left: contextMenu.x, top: contextMenu.y }}
          onClick={(e) => e.stopPropagation()}
        >
          <button
            type="button"
            onClick={() => {
              handleNav('editor', contextMenu.project.id);
              setContextMenu(null);
            }}
            className="w-full text-left px-3 py-1.5 text-xs text-foreground hover:bg-background-hover rounded-lg cursor-pointer"
          >
            Ouvrir
          </button>
          
          <button
            type="button"
            onClick={() => {
              handleRenameProject(contextMenu.project.id, contextMenu.project.title);
              setContextMenu(null);
            }}
            className="w-full text-left px-3 py-1.5 text-xs text-foreground hover:bg-background-hover rounded-lg cursor-pointer"
          >
            Renommer
          </button>

          <div className="border-t border-border my-1" />

          {/* Category Submenu */}
          <div className="relative group">
            <button
              type="button"
              className="w-full text-left px-3 py-1.5 text-xs text-foreground hover:bg-background-hover rounded-lg cursor-pointer flex items-center justify-between"
            >
              <span>Catégorie</span>
              <span className="text-[9px] text-foreground-subtle">➔</span>
            </button>
            <div className="hidden group-hover:flex absolute left-full top-0 ml-0.5 w-44 bg-background-surface border border-border rounded-xl p-1 shadow-lg flex-col gap-0.5 animate-in fade-in slide-in-from-left-1 duration-100">
              <button
                type="button"
                onClick={() => {
                  handleUpdateCategory(contextMenu.project.id, null);
                  setContextMenu(null);
                }}
                className="w-full text-left px-2.5 py-1.5 text-xs text-foreground hover:bg-background-hover rounded-lg cursor-pointer"
              >
                Sans catégorie
              </button>
              {categories.map((cat) => (
                <button
                  key={cat.id}
                  type="button"
                  onClick={() => {
                    handleUpdateCategory(contextMenu.project.id, cat.id);
                    setContextMenu(null);
                  }}
                  className="w-full text-left px-2.5 py-1.5 text-xs text-foreground hover:bg-background-hover rounded-lg cursor-pointer flex items-center gap-1.5"
                >
                  <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: cat.color }} />
                  <span className="truncate">{cat.name}</span>
                </button>
              ))}
            </div>
          </div>

          {/* Statut */}
          <div className="relative group">
            <button
              type="button"
              className="w-full text-left px-3 py-1.5 text-xs text-foreground hover:bg-foreground/[0.04] rounded-lg cursor-pointer flex items-center justify-between"
            >
              <span>Statut</span>
              <span className="text-[9px] text-foreground-subtle">➔</span>
            </button>
            <div className="hidden group-hover:flex absolute left-full top-0 ml-0.5 w-36 bg-background-surface border border-border/40 rounded-xl p-1 shadow-lg flex-col gap-0.5 animate-in fade-in slide-in-from-left-1 duration-100">
              {[
                { value: 'actif', label: 'Actif' },
                { value: 'brouillon', label: 'Brouillon' },
                { value: 'archivé', label: 'Archivé' },
              ].map((s) => (
                <button
                  key={s.value}
                  type="button"
                  onClick={() => {
                    handleUpdateStatus(contextMenu.project.id, s.value);
                    setContextMenu(null);
                  }}
                  className="w-full text-left px-2.5 py-1.5 text-xs text-foreground hover:bg-foreground/[0.04] rounded-lg cursor-pointer"
                >
                  {s.label}
                </button>
              ))}
            </div>
          </div>

          {/* Lier à un projet */}
          <div className="relative group">
            <button
              type="button"
              className="w-full text-left px-3 py-1.5 text-xs text-foreground hover:bg-foreground/[0.04] rounded-lg cursor-pointer flex items-center justify-between"
            >
              <span>Lier à un projet</span>
              <span className="text-[9px] text-foreground-subtle">➔</span>
            </button>
            <div className="hidden group-hover:flex absolute left-full top-0 ml-0.5 w-48 bg-background-surface border border-border/40 rounded-xl p-1 shadow-lg flex-col gap-0.5 max-h-56 overflow-y-auto animate-in fade-in slide-in-from-left-1 duration-100">
              <button
                type="button"
                onClick={() => {
                  handleUpdateParentProject(contextMenu.project.id, null);
                  setContextMenu(null);
                }}
                className="w-full text-left px-2.5 py-1.5 text-xs text-foreground hover:bg-foreground/[0.04] rounded-lg cursor-pointer"
              >
                Aucun (autonome)
              </button>
              {projects
                .filter((p) => p.id !== contextMenu.project.id && !p.parentId)
                .map((proj) => (
                  <button
                    key={proj.id}
                    type="button"
                    onClick={() => {
                      handleUpdateParentProject(contextMenu.project.id, proj.id);
                      setContextMenu(null);
                    }}
                    className="w-full text-left px-2.5 py-1.5 text-xs text-foreground hover:bg-foreground/[0.04] rounded-lg cursor-pointer truncate"
                  >
                    {proj.title}
                  </button>
                ))}
            </div>
          </div>

          <div className="border-t border-border my-1" />

          <button
            type="button"
            onClick={() => {
              handleDeleteProject(contextMenu.project.id, contextMenu.project.title);
              setContextMenu(null);
            }}
            className="w-full text-left px-3 py-1.5 text-xs text-red-400 hover:bg-red-500/10 rounded-lg cursor-pointer"
          >
            Supprimer
          </button>
        </div>
      )}
    </>
  );
};

export default Sidebar;
