import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { Block, BlockType, PresenceUser } from '../../types/block.js';
import { CanvasGrid } from './CanvasGrid.js';
import { BLOCK_META } from '../editor/BlockItem.js';
import { RichTextBlock } from '../editor/blocks/RichTextBlock.js';
import { MarkdownBlock } from '../editor/blocks/MarkdownBlock.js';
import { DrawingBlock } from '../editor/blocks/DrawingBlock.js';
import { ChecklistBlock } from '../editor/blocks/ChecklistBlock.js';
import { TableBlock } from '../editor/blocks/TableBlock.js';
import { MediaBlock } from '../editor/blocks/MediaBlock.js';
import { EmbedBlock } from '../editor/blocks/EmbedBlock.js';
import { CodeBlock } from '../editor/blocks/CodeBlock.js';
import {
  ZoomIn,
  ZoomOut,
  RotateCcw,
  Maximize,
  GripHorizontal,
  Trash2,
  Copy,
  Plus,
  Heading1,
  Heading2,
  Bold,
  Italic,
  Underline,
  List,
  Link as LinkIcon,
  Trash,
} from 'lucide-react';

interface InfiniteCanvasProps {
  blocks: Block[];
  panX: number;
  panY: number;
  zoom: number;
  onViewportChange: (panX: number, panY: number, zoom: number) => void;
  onUpdateBlock: (blockId: string, content: any) => void;
  onUpdateBlockPosition: (blockId: string, pos: { canvasX?: number; canvasY?: number; canvasW?: number; canvasH?: number; canvasZ?: number }) => void;
  onDeleteBlock: (blockId: string) => void;
  onDuplicateBlock: (block: Block) => void;
  onAddBlock: (type: BlockType, canvasX?: number, canvasY?: number) => void;
  onCursorMove?: (worldX: number, worldY: number, blockId?: string) => void;
  activeCollaborators?: PresenceUser[];
  readOnly?: boolean;
}

type ResizeHandle = 'nw' | 'n' | 'ne' | 'e' | 'se' | 's' | 'sw' | 'w';

// Helper to auto-layout blocks that have no canvas coordinates
export function initializeMissingCanvasCoordinates(blocks: Block[]): Block[] {
  const columnWidth = 380;
  const rowHeight = 300;
  const columns = 3;
  const paddingX = 80;
  const paddingY = 80;

  return blocks.map((block, index) => {
    if (block.canvasX !== null && block.canvasX !== undefined) {
      return block;
    }
    const col = index % columns;
    const row = Math.floor(index / columns);
    return {
      ...block,
      canvasX: paddingX + col * columnWidth,
      canvasY: paddingY + row * rowHeight,
      canvasW: block.canvasW || 340,
      canvasH: block.canvasH || 260,
      canvasZ: block.canvasZ || index,
    };
  });
}

export const InfiniteCanvas: React.FC<InfiniteCanvasProps> = ({
  blocks: rawBlocks,
  panX,
  panY,
  zoom,
  onViewportChange,
  onUpdateBlock,
  onUpdateBlockPosition,
  onDeleteBlock,
  onDuplicateBlock,
  onAddBlock,
  onCursorMove,
  activeCollaborators = [],
  readOnly = false,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [containerSize, setContainerSize] = useState({ width: 1000, height: 700 });
  const [selectedBlockId, setSelectedBlockId] = useState<string | null>(null);

  // Dragging / Panning State
  const [isPanning, setIsPanning] = useState(false);
  const panStartRef = useRef<{ startX: number; startY: number; initPanX: number; initPanY: number }>({
    startX: 0,
    startY: 0,
    initPanX: panX,
    initPanY: panY,
  });

  // Block Move State
  const [movingBlockId, setMovingBlockId] = useState<string | null>(null);
  const blockMoveStartRef = useRef<{ startX: number; startY: number; initX: number; initY: number }>({
    startX: 0,
    startY: 0,
    initX: 0,
    initY: 0,
  });

  // Block Resize State
  const [activeGuides, setActiveGuides] = useState<{ x?: number; y?: number } | null>(null);
  const [contextMenu, setContextMenu] = useState<{
    block?: Block;
    x: number;
    y: number;
    worldX?: number;
    worldY?: number;
  } | null>(null);
  const [addFabOpen, setAddFabOpen] = useState(false);
  const [resizingState, setResizingState] = useState<{
    blockId: string;
    handle: ResizeHandle;
    startX: number;
    startY: number;
    initX: number;
    initY: number;
    initW: number;
    initH: number;
  } | null>(null);

  // Initialize block coordinates
  const blocks = React.useMemo(() => initializeMissingCanvasCoordinates(rawBlocks), [rawBlocks]);

  // Track container dimensions
  useEffect(() => {
    const updateSize = () => {
      if (containerRef.current) {
        setContainerSize({
          width: containerRef.current.clientWidth,
          height: containerRef.current.clientHeight,
        });
      }
    };
    updateSize();
    window.addEventListener('resize', updateSize);
    return () => window.removeEventListener('resize', updateSize);
  }, []);

  // Close context menu on global click or right-click
  useEffect(() => {
    const handleGlobalClick = () => {
      setContextMenu(null);
    };
    window.addEventListener('click', handleGlobalClick);
    window.addEventListener('contextmenu', handleGlobalClick);
    return () => {
      window.removeEventListener('click', handleGlobalClick);
      window.removeEventListener('contextmenu', handleGlobalClick);
    };
  }, []);

  // Prevent browser default context menu inside the canvas container
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const handleNativeContextMenu = (e: MouseEvent) => {
      e.preventDefault();
    };
    el.addEventListener('contextmenu', handleNativeContextMenu, true);
    return () => {
      el.removeEventListener('contextmenu', handleNativeContextMenu, true);
    };
  }, []);

  // Affine Transformations
  const screenToWorld = useCallback(
    (screenX: number, screenY: number): { x: number; y: number } => {
      const z = Math.max(0.1, Math.min(3.0, zoom));
      return {
        x: screenX / z - panX,
        y: screenY / z - panY,
      };
    },
    [panX, panY, zoom]
  );

  // Wheel Zoom with cursor invariance
  const handleWheel = (e: React.WheelEvent<HTMLDivElement>) => {
    e.preventDefault();
    const rect = containerRef.current?.getBoundingClientRect();
    if (!rect) return;

    const pivotX = e.clientX - rect.left;
    const pivotY = e.clientY - rect.top;

    // Zoom centered on mouse directly on wheel scroll
    const zoomFactor = e.deltaY < 0 ? 1.05 : 0.95;
    const targetZoom = Math.min(3.0, Math.max(0.1, zoom * zoomFactor));

    if (targetZoom !== zoom) {
      const newPanX = panX + pivotX * (1 / targetZoom - 1 / zoom);
      const newPanY = panY + pivotY * (1 / targetZoom - 1 / zoom);
      onViewportChange(newPanX, newPanY, targetZoom);
    }
  };

  // Zoom button handler (centered on viewport)
  const handleZoomButtons = (factor: number) => {
    const targetZoom = Math.min(3.0, Math.max(0.1, zoom * factor));
    if (targetZoom !== zoom) {
      const pivotX = containerSize.width / 2;
      const pivotY = containerSize.height / 2;
      const newPanX = panX + pivotX * (1 / targetZoom - 1 / zoom);
      const newPanY = panY + pivotY * (1 / targetZoom - 1 / zoom);
      onViewportChange(newPanX, newPanY, targetZoom);
    }
  };

  const handleResetZoom = () => {
    const targetZoom = 1.0;
    const pivotX = containerSize.width / 2;
    const pivotY = containerSize.height / 2;
    const newPanX = panX + pivotX * (1 / targetZoom - 1 / zoom);
    const newPanY = panY + pivotY * (1 / targetZoom - 1 / zoom);
    onViewportChange(newPanX, newPanY, targetZoom);
  };

  const handleCenterContent = () => {
    if (blocks.length === 0) {
      onViewportChange(0, 0, 1.0);
      return;
    }

    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const b of blocks) {
      const bx = b.canvasX ?? 0;
      const by = b.canvasY ?? 0;
      const bw = b.canvasW ?? 320;
      const bh = b.canvasH ?? 240;
      if (bx < minX) minX = bx;
      if (by < minY) minY = by;
      if (bx + bw > maxX) maxX = bx + bw;
      if (by + bh > maxY) maxY = by + bh;
    }

    const contentCenterX = (minX + maxX) / 2;
    const contentCenterY = (minY + maxY) / 2;

    const newPanX = containerSize.width / (2 * zoom) - contentCenterX;
    const newPanY = containerSize.height / (2 * zoom) - contentCenterY;
    onViewportChange(newPanX, newPanY, zoom);
  };

  // Pointer Down on Canvas (Start Pan)
  const handleCanvasPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (e.target !== containerRef.current && (e.target as HTMLElement).getAttribute('data-canvas-bg') !== 'true') {
      return;
    }

    setIsPanning(true);
    panStartRef.current = {
      startX: e.clientX,
      startY: e.clientY,
      initPanX: panX,
      initPanY: panY,
    };
    setSelectedBlockId(null);
  };

  // Block Move Start
  const handleBlockHeaderPointerDown = (e: React.PointerEvent, block: Block) => {
    if (readOnly) return;
    e.stopPropagation();

    setSelectedBlockId(block.id);
    setMovingBlockId(block.id);

    // Bring to front
    const maxZ = Math.max(...blocks.map((b) => b.canvasZ ?? 0), 0);
    onUpdateBlockPosition(block.id, { canvasZ: maxZ + 1 });

    blockMoveStartRef.current = {
      startX: e.clientX,
      startY: e.clientY,
      initX: block.canvasX ?? 0,
      initY: block.canvasY ?? 0,
    };
  };

  // Block Resize Start
  const handleResizePointerDown = (e: React.PointerEvent, block: Block, handle: ResizeHandle) => {
    if (readOnly) return;
    e.stopPropagation();

    setSelectedBlockId(block.id);
    setResizingState({
      blockId: block.id,
      handle,
      startX: e.clientX,
      startY: e.clientY,
      initX: block.canvasX ?? 0,
      initY: block.canvasY ?? 0,
      initW: block.canvasW ?? 320,
      initH: block.canvasH ?? 240,
    });
  };

  // Pointer Move (Handles Panning, Moving, Resizing, and Live Cursor Tracking)
  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    const rect = containerRef.current?.getBoundingClientRect();
    if (rect && onCursorMove) {
      const mouseScreenX = e.clientX - rect.left;
      const mouseScreenY = e.clientY - rect.top;
      const worldPos = screenToWorld(mouseScreenX, mouseScreenY);
      onCursorMove(worldPos.x, worldPos.y, movingBlockId || resizingState?.blockId || selectedBlockId || undefined);
    }

    // 1. Panning Canvas
    if (isPanning) {
      const deltaScreenX = e.clientX - panStartRef.current.startX;
      const deltaScreenY = e.clientY - panStartRef.current.startY;
      const newPanX = panStartRef.current.initPanX + deltaScreenX / zoom;
      const newPanY = panStartRef.current.initPanY + deltaScreenY / zoom;
      onViewportChange(newPanX, newPanY, zoom);
      return;
    }

    // 2. Moving Block
    if (movingBlockId) {
      const deltaScreenX = e.clientX - blockMoveStartRef.current.startX;
      const deltaScreenY = e.clientY - blockMoveStartRef.current.startY;
      const deltaWorldX = deltaScreenX / zoom;
      const deltaWorldY = deltaScreenY / zoom;

      const rawX = blockMoveStartRef.current.initX + deltaWorldX;
      const rawY = blockMoveStartRef.current.initY + deltaWorldY;

      const targetBlock = blocks.find((b) => b.id === movingBlockId);
      const w = targetBlock?.canvasW || 340;
      const h = targetBlock?.canvasH || 260;

      // Smart Snapping calculations
      const snapThreshold = 12; // pixels
      let snappedX = rawX;
      let snappedY = rawY;
      let guides: { x?: number; y?: number } = {};

      const otherBlocks = blocks.filter(
        (b) => b.id !== movingBlockId && b.canvasX !== null && b.canvasX !== undefined
      );

      for (const ob of otherBlocks) {
        const obX = ob.canvasX!;
        const obY = ob.canvasY!;
        const obW = ob.canvasW || 340;
        const obH = ob.canvasH || 260;
        const obRight = obX + obW;
        const obBottom = obY + obH;

        const right = rawX + w;
        const bottom = rawY + h;

        // X Snapping
        if (Math.abs(rawX - obX) < snapThreshold) {
          snappedX = obX;
          guides.x = obX;
        } else if (Math.abs(rawX - obRight) < snapThreshold) {
          snappedX = obRight;
          guides.x = obRight;
        } else if (Math.abs(right - obX) < snapThreshold) {
          snappedX = obX - w;
          guides.x = obX;
        } else if (Math.abs(right - obRight) < snapThreshold) {
          snappedX = obRight - w;
          guides.x = obRight;
        }

        // Y Snapping
        if (Math.abs(rawY - obY) < snapThreshold) {
          snappedY = obY;
          guides.y = obY;
        } else if (Math.abs(rawY - obBottom) < snapThreshold) {
          snappedY = obBottom;
          guides.y = obBottom;
        } else if (Math.abs(bottom - obY) < snapThreshold) {
          snappedY = obY - h;
          guides.y = obY;
        } else if (Math.abs(bottom - obBottom) < snapThreshold) {
          snappedY = obBottom - h;
          guides.y = obBottom;
        }
      }

      setActiveGuides(guides);

      onUpdateBlockPosition(movingBlockId, {
        canvasX: Math.round(snappedX),
        canvasY: Math.round(snappedY),
      });
      return;
    }

    // 3. Resizing Block
    if (resizingState) {
      const { blockId, handle, startX, startY, initX, initY, initW, initH } = resizingState;
      const deltaWorldX = (e.clientX - startX) / zoom;
      const deltaWorldY = (e.clientY - startY) / zoom;

      let newX = initX;
      let newY = initY;
      let newW = initW;
      let newH = initH;

      if (handle.includes('e')) newW = Math.max(200, initW + deltaWorldX);
      if (handle.includes('s')) newH = Math.max(120, initH + deltaWorldY);
      if (handle.includes('w')) {
        const potentialW = initW - deltaWorldX;
        if (potentialW >= 200) {
          newW = potentialW;
          newX = initX + deltaWorldX;
        }
      }
      if (handle.includes('n')) {
        const potentialH = initH - deltaWorldY;
        if (potentialH >= 120) {
          newH = potentialH;
          newY = initY + deltaWorldY;
        }
      }

      onUpdateBlockPosition(blockId, {
        canvasX: Math.round(newX),
        canvasY: Math.round(newY),
        canvasW: Math.round(newW),
        canvasH: Math.round(newH),
      });
    }
  };

  const handlePointerUp = () => {
    setIsPanning(false);
    setMovingBlockId(null);
    setResizingState(null);
    setActiveGuides(null);
  };

  const handleDoubleClickBg = (e: React.MouseEvent) => {
    if (e.target === containerRef.current || (e.target as HTMLElement).getAttribute('data-canvas-bg') === 'true') {
      handleCenterContent();
    }
  };

  const handleQuickAddBlock = (type: BlockType) => {
    // Place block near center of current viewport
    const centerWorld = screenToWorld(containerSize.width / 2 - 160, containerSize.height / 2 - 120);
    onAddBlock(type, Math.round(centerWorld.x), Math.round(centerWorld.y));
  };

  const handleCanvasContextMenu = (e: React.MouseEvent) => {
    if (readOnly) return;
    e.preventDefault();
    e.stopPropagation();
    const rect = containerRef.current?.getBoundingClientRect();
    if (!rect) return;
    const localX = e.clientX - rect.left;
    const localY = e.clientY - rect.top;
    const world = screenToWorld(localX, localY);
    setContextMenu({
      x: e.clientX,
      y: e.clientY,
      worldX: world.x,
      worldY: world.y,
    });
  };

  return (
    <div
      ref={containerRef}
      onWheel={handleWheel}
      onPointerDown={handleCanvasPointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerCancel={handlePointerUp}
      onDoubleClick={handleDoubleClickBg}
      onContextMenu={handleCanvasContextMenu}
      className={`relative w-full h-[calc(100vh-8rem)] bg-background overflow-hidden select-none touch-none ${
        isPanning ? 'cursor-grabbing' : 'cursor-grab'
      }`}
      data-canvas-bg="true"
    >
      {/* 2D Background Grid */}
      <CanvasGrid panX={panX} panY={panY} zoom={zoom} />

      {/* World Transform Layer */}
      <div
        className="absolute origin-top-left pointer-events-none"
        style={{
          transform: `scale(${zoom}) translate(${panX}px, ${panY}px)`,
        }}
      >
        {/* Snapping Guide Lines */}
        {activeGuides?.x !== undefined && (
          <div
            className="absolute border-l border-dashed border-accent/80 pointer-events-none"
            style={{
              left: `${activeGuides.x}px`,
              top: '-10000px',
              bottom: '-10000px',
              width: '0px',
              zIndex: 9999,
            }}
          />
        )}
        {activeGuides?.y !== undefined && (
          <div
            className="absolute border-t border-dashed border-accent/80 pointer-events-none"
            style={{
              top: `${activeGuides.y}px`,
              left: '-10000px',
              right: '-10000px',
              height: '0px',
              zIndex: 9999,
            }}
          />
        )}

        {blocks.map((block) => {
          const isSelected = selectedBlockId === block.id;
          const meta = BLOCK_META[block.type] || {
            label: block.type,
            icon: GripHorizontal,
            color: 'text-foreground bg-background border-border',
          };
          const Icon = meta.icon;
          const activeCollab = activeCollaborators.find((u) => u.cursor?.blockId === block.id);

          return (
            <div
              key={block.id}
              onClick={(e) => {
                e.stopPropagation();
                setSelectedBlockId(block.id);
              }}
              onContextMenu={(e) => {
                e.preventDefault();
                e.stopPropagation();
                setSelectedBlockId(block.id);
                setContextMenu({
                  block,
                  x: e.clientX,
                  y: e.clientY,
                });
              }}
              className={`absolute pointer-events-auto rounded-xl flex flex-col transition-all duration-150 ${
                isSelected
                  ? 'border border-border bg-background-surface shadow-md'
                  : 'border border-border/40 bg-background-surface shadow-xs hover:border-border/80'
              }`}
              style={{
                left: `${block.canvasX ?? 0}px`,
                top: `${block.canvasY ?? 0}px`,
                width: `${block.canvasW ?? 340}px`,
                minHeight: `${block.canvasH ?? 240}px`,
                zIndex: (block.canvasZ ?? 0) + (isSelected ? 50 : 1),
                boxShadow: activeCollab ? `0 0 0 2px ${activeCollab.color}` : undefined,
              }}
            >
              {/* Invisible drag handle — entire top area */}
              {!readOnly && (
                <div
                  onPointerDown={(e) => handleBlockHeaderPointerDown(e, block)}
                  className="absolute top-0 left-0 right-0 h-6 cursor-grab active:cursor-grabbing z-10"
                />
              )}

              {/* Block Body */}
              <div className="p-3 flex-1 overflow-auto">
                {block.type === 'rich_text' && (
                  <RichTextBlock
                    content={block.content as any}
                    onChange={(c) => onUpdateBlock(block.id, c)}
                    readOnly={readOnly}
                    isToolbarVisible={false}
                  />
                )}
                {block.type === 'markdown' && (
                  <MarkdownBlock
                    content={block.content as any}
                    onChange={(c) => onUpdateBlock(block.id, c)}
                    readOnly={readOnly}
                    isToolbarVisible={isSelected}
                  />
                )}
                {block.type === 'drawing' && (
                  <DrawingBlock
                    content={block.content as any}
                    onChange={(c) => onUpdateBlock(block.id, c)}
                    readOnly={readOnly}
                    isToolbarVisible={isSelected}
                  />
                )}
                {block.type === 'checklist' && (
                  <ChecklistBlock
                    content={block.content as any}
                    onChange={(c) => onUpdateBlock(block.id, c)}
                    readOnly={readOnly}
                    isToolbarVisible={isSelected}
                  />
                )}
                {block.type === 'table' && (
                  <TableBlock
                    content={block.content as any}
                    onChange={(c) => onUpdateBlock(block.id, c)}
                    readOnly={readOnly}
                    isToolbarVisible={isSelected}
                  />
                )}
                {block.type === 'media' && (
                  <MediaBlock
                    content={block.content as any}
                    onChange={(c) => onUpdateBlock(block.id, c)}
                    readOnly={readOnly}
                    isToolbarVisible={isSelected}
                  />
                )}
                {block.type === 'embed' && (
                  <EmbedBlock
                    content={block.content as any}
                    onChange={(c) => onUpdateBlock(block.id, c)}
                    readOnly={readOnly}
                    isToolbarVisible={isSelected}
                  />
                )}
                {block.type === 'code' && (
                  <CodeBlock
                    content={block.content as any}
                    onChange={(c) => onUpdateBlock(block.id, c)}
                    readOnly={readOnly}
                    isToolbarVisible={isSelected}
                  />
                )}
              </div>

              {/* Subtle Resize Handle in bottom right */}
              {isSelected && !readOnly && (
                <div
                  onPointerDown={(e) => handleResizePointerDown(e, block, 'se')}
                  className="absolute bottom-1 right-1 w-3.5 h-3.5 cursor-nwse-resize z-20 flex items-end justify-end p-0.5 text-foreground-subtle/40 hover:text-foreground/80 transition-colors select-none"
                >
                  <svg width="8" height="8" viewBox="0 0 8 8" fill="none" stroke="currentColor" strokeWidth="1.5">
                    <line x1="6" y1="2" x2="2" y2="6" />
                    <line x1="6" y1="4" x2="4" y2="6" />
                  </svg>
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* Floating HUD Controls (Bottom Left) */}
      <div className="absolute bottom-4 left-4 z-30 flex items-center gap-1 bg-card/90 backdrop-blur-md border border-border rounded-xl p-1 shadow-2xl">
        <button
          type="button"
          onClick={() => handleZoomButtons(0.85)}
          className="p-2 rounded-lg text-foreground hover:bg-background-surface transition-colors"
          title="Zoom Out"
        >
          <ZoomOut className="w-4 h-4" />
        </button>

        <button
          type="button"
          onClick={handleResetZoom}
          className="px-2 py-1 rounded-lg text-xs font-mono font-bold text-foreground hover:bg-background-surface transition-colors min-w-[3.5rem] text-center"
          title="Reset Zoom (100%)"
        >
          {Math.round(zoom * 100)}%
        </button>

        <button
          type="button"
          onClick={() => handleZoomButtons(1.15)}
          className="p-2 rounded-lg text-foreground hover:bg-background-surface transition-colors"
          title="Zoom In"
        >
          <ZoomIn className="w-4 h-4" />
        </button>

        <div className="w-px h-4 bg-border mx-0.5 border-border" />

        <button
          type="button"
          onClick={handleCenterContent}
          className="p-2 rounded-lg text-foreground hover:bg-background-surface transition-colors"
          title="Fit & Center View (Double click bg)"
        >
          <Maximize className="w-4 h-4" />
        </button>

        <button
          type="button"
          onClick={() => onViewportChange(0, 0, 1.0)}
          className="p-2 rounded-lg text-foreground hover:bg-background-surface transition-colors"
          title="Reset View to Origin"
        >
          <RotateCcw className="w-4 h-4" />
        </button>
      </div>

      {/* FAB Add Block Button (bottom right) */}
      {!readOnly && (
        <div className="absolute bottom-4 right-4 z-30">
          <div className="relative">
            <button
              type="button"
              onClick={() => setAddFabOpen((prev) => !prev)}
              className="w-10 h-10 rounded-xl bg-foreground text-background flex items-center justify-center hover:opacity-80 transition-opacity cursor-pointer shadow-md"
              title="Ajouter un bloc"
            >
              <Plus className="w-5 h-5" />
            </button>

            {addFabOpen && (
              <div className="absolute bottom-12 right-0 w-48 bg-background-surface border border-border rounded-xl p-1 shadow-lg">
                {(Object.keys(BLOCK_META) as BlockType[]).map((type) => {
                  const m = BLOCK_META[type];
                  const Ic = m.icon;
                  return (
                    <button
                      key={type}
                      type="button"
                      onClick={() => {
                        handleQuickAddBlock(type);
                        setAddFabOpen(false);
                      }}
                      className="w-full flex items-center gap-2 px-3 py-2 text-sm text-foreground hover:bg-background-hover rounded-lg cursor-pointer"
                    >
                      <Ic className="w-4 h-4 text-foreground-muted" />
                      <span>{m.label}</span>
                    </button>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Right-click Context Menu */}
      {contextMenu && (
        <div
          className="fixed z-50 w-52 bg-background-surface border border-border shadow-lg rounded-xl p-1.5 flex flex-col gap-0.5 pointer-events-auto"
          style={{
            left: `${contextMenu.x}px`,
            top: `${contextMenu.y}px`,
          }}
          onClick={(e) => e.stopPropagation()}
        >
          {contextMenu.block ? (
            <>
              <button
                type="button"
                onClick={() => {
                  onDuplicateBlock(contextMenu.block!);
                  setContextMenu(null);
                }}
                className="w-full flex items-center gap-2 px-2.5 py-1.5 text-xs text-foreground hover:bg-background-hover rounded-lg text-left cursor-pointer"
              >
                <Copy className="w-3.5 h-3.5 text-foreground-muted" />
                <span>Dupliquer</span>
              </button>
              <button
                type="button"
                onClick={() => {
                  onDeleteBlock(contextMenu.block!.id);
                  setContextMenu(null);
                }}
                className="w-full flex items-center gap-2 px-2.5 py-1.5 text-xs text-red-400 hover:bg-red-500/10 rounded-lg text-left cursor-pointer"
              >
                <Trash2 className="w-3.5 h-3.5" />
                <span>Supprimer</span>
              </button>
            </>
          ) : (
            <>
              <div className="px-2.5 py-1 text-[10px] font-semibold text-foreground-subtle uppercase">
                Créer un bloc
              </div>
              {(Object.keys(BLOCK_META) as BlockType[]).map((type) => {
                const m = BLOCK_META[type];
                const Ic = m.icon;
                return (
                  <button
                    key={type}
                    type="button"
                    onClick={() => {
                      onAddBlock(type, contextMenu.worldX, contextMenu.worldY);
                      setContextMenu(null);
                    }}
                    className="w-full flex items-center gap-2 px-2.5 py-1.5 text-xs text-foreground hover:bg-background-hover rounded-lg text-left cursor-pointer"
                  >
                    <Ic className="w-3.5 h-3.5 text-foreground-muted" />
                    <span>{m.label}</span>
                  </button>
                );
              })}
              <div className="border-t border-border my-1" />
              <button
                type="button"
                onClick={() => {
                  onViewportChange(0, 0, 1.0);
                  setContextMenu(null);
                }}
                className="w-full flex items-center gap-2 px-2.5 py-1.5 text-xs text-foreground hover:bg-background-hover rounded-lg text-left cursor-pointer"
              >
                <RotateCcw className="w-3.5 h-3.5 text-foreground-muted" />
                <span>Réinitialiser la vue</span>
              </button>
            </>
          )}
        </div>
      )}

      {/* Floating Formatting Toolbar (Top Center) when a block is selected */}
      {selectedBlockId && !readOnly && (() => {
        const selectedBlock = blocks.find((b) => b.id === selectedBlockId);
        if (!selectedBlock || (selectedBlock.type !== 'rich_text' && selectedBlock.type !== 'markdown')) return null;

        const handleFormat = (command: string, value: string = '') => {
          document.execCommand(command, false, value);
          const activeEl = document.activeElement as HTMLElement;
          if (activeEl && activeEl.contentEditable === 'true') {
            const event = new Event('input', { bubbles: true });
            activeEl.dispatchEvent(event);
          }
        };

        const handleLink = () => {
          const url = prompt('URL du lien :');
          if (url) {
            const formattedUrl = (!url.startsWith('http://') && !url.startsWith('https://') && !url.startsWith('/'))
              ? `https://${url}`
              : url;
            handleFormat('createLink', formattedUrl);
          }
        };

        return (
          <div
            className="absolute top-4 left-1/2 -translate-x-1/2 z-40 bg-background-surface border border-border rounded-xl px-2 py-1 shadow-lg flex items-center gap-0.5 select-none animate-in fade-in slide-in-from-top-2 duration-150"
            onClick={(e) => e.stopPropagation()}
          >
            {/* H1, H2 */}
            <button
              type="button"
              onMouseDown={(e) => { e.preventDefault(); handleFormat('formatBlock', '<h1>'); }}
              title="Titre 1"
              className="p-1.5 rounded-lg hover:bg-background-hover hover:text-foreground text-foreground-muted transition-colors cursor-pointer"
            >
              <Heading1 className="w-3.5 h-3.5" />
            </button>
            <button
              type="button"
              onMouseDown={(e) => { e.preventDefault(); handleFormat('formatBlock', '<h2>'); }}
              title="Titre 2"
              className="p-1.5 rounded-lg hover:bg-background-hover hover:text-foreground text-foreground-muted transition-colors cursor-pointer"
            >
              <Heading2 className="w-3.5 h-3.5" />
            </button>

            <div className="w-px h-4 bg-border mx-1 border-border" />

            {/* Bold, Italic, Underline */}
            <button
              type="button"
              onMouseDown={(e) => { e.preventDefault(); handleFormat('bold'); }}
              title="Gras"
              className="p-1.5 rounded-lg hover:bg-background-hover hover:text-foreground text-foreground-muted transition-colors cursor-pointer"
            >
              <Bold className="w-3.5 h-3.5" />
            </button>
            <button
              type="button"
              onMouseDown={(e) => { e.preventDefault(); handleFormat('italic'); }}
              title="Italique"
              className="p-1.5 rounded-lg hover:bg-background-hover hover:text-foreground text-foreground-muted transition-colors cursor-pointer"
            >
              <Italic className="w-3.5 h-3.5" />
            </button>
            <button
              type="button"
              onMouseDown={(e) => { e.preventDefault(); handleFormat('underline'); }}
              title="Souligné"
              className="p-1.5 rounded-lg hover:bg-background-hover hover:text-foreground text-foreground-muted transition-colors cursor-pointer"
            >
              <Underline className="w-3.5 h-3.5" />
            </button>

            <div className="w-px h-4 bg-border mx-1 border-border" />

            {/* Lists & Link */}
            <button
              type="button"
              onMouseDown={(e) => { e.preventDefault(); handleFormat('insertUnorderedList'); }}
              title="Liste à puces"
              className="p-1.5 rounded-lg hover:bg-background-hover hover:text-foreground text-foreground-muted transition-colors cursor-pointer"
            >
              <List className="w-3.5 h-3.5" />
            </button>
            <button
              type="button"
              onMouseDown={(e) => { e.preventDefault(); handleLink(); }}
              title="Insérer un lien"
              className="p-1.5 rounded-lg hover:bg-background-hover hover:text-foreground text-foreground-muted transition-colors cursor-pointer"
            >
              <LinkIcon className="w-3.5 h-3.5" />
            </button>

            <div className="w-px h-4 bg-border mx-1 border-border" />

            {/* Delete block */}
            <button
              type="button"
              onClick={() => {
                onDeleteBlock(selectedBlockId);
                setSelectedBlockId(null);
              }}
              title="Supprimer le bloc"
              className="p-1.5 rounded-lg hover:bg-red-500/10 text-red-400 transition-colors cursor-pointer"
            >
              <Trash className="w-3.5 h-3.5" />
            </button>
          </div>
        );
      })()}
    </div>
  );
};
