import React, { useState, useEffect, useCallback } from 'react';
import { Plus, Trash2, Edit2, User, Upload } from 'lucide-react';
import type { Category, Tag } from '../../types/project.js';
import { api } from '../../lib/api.js';
import { useAuth } from '../../context/AuthContext.js';

export const CategoriesView: React.FC = () => {
  const { user, refreshUser } = useAuth();
  const [categories, setCategories] = useState<Category[]>([]);
  const [tags, setTags] = useState<Tag[]>([]);
  const [isLoadingCats, setIsLoadingCats] = useState<boolean>(true);
  const [isLoadingTags, setIsLoadingTags] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  // Profile Form State
  const [profileName, setProfileName] = useState(user?.name || '');
  const [profileAvatar, setProfileAvatar] = useState(user?.avatar || '');
  const [isSavingProfile, setIsSavingProfile] = useState(false);
  const [profileSuccess, setProfileSuccess] = useState(false);

  // Category Form State
  const [isCatModalOpen, setIsCatModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState<Category | null>(null);
  const [catName, setCatName] = useState('');
  const [catColor, setCatColor] = useState('#6366f1');
  const [catDescription, setCatDescription] = useState('');
  const [isSavingCat, setIsSavingCat] = useState(false);

  // Tag Form State
  const [newTagName, setNewTagName] = useState('');
  const [isSavingTag, setIsSavingTag] = useState(false);

  useEffect(() => {
    if (user) {
      setProfileName(user.name);
      setProfileAvatar(user.avatar || '');
    }
  }, [user]);

  const handleAvatarFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > 1.5 * 1024 * 1024) {
      alert('L\'image de profil est trop volumineuse (maximum 1.5 Mo).');
      return;
    }

    const reader = new FileReader();
    reader.onload = () => {
      if (typeof reader.result === 'string') {
        setProfileAvatar(reader.result);
      }
    };
    reader.readAsDataURL(file);
  };

  const fetchCategories = useCallback(async () => {
    setIsLoadingCats(true);
    try {
      const response = await api.get<{ categories: Category[] }>('/api/categories');
      setCategories(response.categories);
    } catch (err: any) {
      setError(err.message || 'Failed to load categories');
    } finally {
      setIsLoadingCats(false);
    }
  }, []);

  const fetchTags = useCallback(async () => {
    setIsLoadingTags(true);
    try {
      const response = await api.get<{ tags: Tag[] }>('/api/tags');
      setTags(response.tags);
    } catch (err: any) {
      setError(err.message || 'Failed to load tags');
    } finally {
      setIsLoadingTags(false);
    }
  }, []);

  useEffect(() => {
    fetchCategories();
    fetchTags();
  }, [fetchCategories, fetchTags]);

  const handleProfileSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!profileName.trim()) return;

    setIsSavingProfile(true);
    setError(null);
    setProfileSuccess(false);
    try {
      await api.patch('/api/auth/profile', {
        name: profileName.trim(),
        avatar: profileAvatar.trim() || null,
      });
      await refreshUser();
      setProfileSuccess(true);
      setTimeout(() => setProfileSuccess(false), 3000);
    } catch (err: any) {
      setError(err.message || 'Failed to save profile');
    } finally {
      setIsSavingProfile(false);
    }
  };

  const openCreateCatModal = () => {
    setEditingCategory(null);
    setCatName('');
    setCatColor('#6366f1');
    setCatDescription('');
    setIsCatModalOpen(true);
  };

  const openEditCatModal = (cat: Category) => {
    setEditingCategory(cat);
    setCatName(cat.name);
    setCatColor(cat.color || '#6366f1');
    setCatDescription(cat.description || '');
    setIsCatModalOpen(true);
  };

  const handleCatSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!catName.trim()) return;

    setIsSavingCat(true);
    setError(null);
    try {
      if (editingCategory) {
        await api.patch(`/api/categories/${editingCategory.id}`, {
          name: catName.trim(),
          color: catColor,
          description: catDescription.trim(),
        });
      } else {
        await api.post('/api/categories', {
          name: catName.trim(),
          color: catColor,
          description: catDescription.trim(),
        });
      }
      setIsCatModalOpen(false);
      await fetchCategories();
    } catch (err: any) {
      setError(err.message || 'Failed to save category');
    } finally {
      setIsSavingCat(false);
    }
  };

  const handleCatDelete = async (id: string, name: string) => {
    if (!window.confirm(`Supprimer la catégorie "${name}" ?`)) return;
    try {
      await api.delete(`/api/categories/${id}`);
      await fetchCategories();
    } catch (err: any) {
      setError(err.message || 'Failed to delete category');
    }
  };

  const handleTagSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTagName.trim()) return;

    setIsSavingTag(true);
    setError(null);
    try {
      await api.post('/api/tags', { name: newTagName.trim() });
      setNewTagName('');
      await fetchTags();
    } catch (err: any) {
      setError(err.message || 'Failed to create tag');
    } finally {
      setIsSavingTag(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-4xl mx-auto px-6 py-10 overflow-y-auto">
      {error && (
        <div className="p-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-400 text-xs mb-6">
          {error}
        </div>
      )}

      {/* Account Profile Section */}
      <div className="mb-12">
        <h1 className="text-xl font-bold text-foreground mb-6 flex items-center gap-2">
          <User className="w-5 h-5" />
          Mon Compte
        </h1>
        
        <form onSubmit={handleProfileSubmit} className="max-w-md bg-background-surface border border-border rounded-xl p-5 space-y-4">
          <div className="flex items-center gap-4 mb-2">
            {/* Avatar Display & Upload */}
            <div className="relative group shrink-0 w-16 h-16 rounded-2xl bg-foreground/[0.04] border border-border flex items-center justify-center overflow-hidden">
              {profileAvatar ? (
                <img src={profileAvatar} alt="Avatar" className="w-full h-full object-cover" />
              ) : (
                <span className="text-xl font-bold text-foreground-muted">
                  {profileName ? profileName.charAt(0).toUpperCase() : 'U'}
                </span>
              )}
              <label className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 flex flex-col items-center justify-center text-[9px] text-white cursor-pointer transition-opacity">
                <Upload className="w-3.5 h-3.5 mb-1" />
                <span>Modifier</span>
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleAvatarFileChange}
                  className="hidden"
                />
              </label>
            </div>
            <div className="flex-1 space-y-1">
              <span className="text-[11px] font-semibold text-foreground-muted uppercase tracking-wider">
                Photo de profil
              </span>
              <p className="text-xs text-foreground-subtle">
                Cliquez pour importer une image (maximum 1.5 Mo).
              </p>
            </div>
          </div>

          <div>
            <label className="block text-xs font-semibold text-foreground-muted mb-1">
              Nom d'utilisateur
            </label>
            <input
              type="text"
              required
              value={profileName}
              onChange={(e) => setProfileName(e.target.value)}
              placeholder="Votre nom"
              className="w-full px-3 py-2 bg-background border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-foreground/30 transition-colors"
            />
          </div>

          <div className="flex items-center justify-between pt-2 border-t border-border/40">
            {profileSuccess && (
              <span className="text-xs text-emerald-400 font-semibold">✓ Modifications enregistrées</span>
            )}
            <button
              type="submit"
              disabled={isSavingProfile || !profileName.trim()}
              className="ml-auto px-4 py-2 bg-foreground text-background rounded-lg text-xs font-semibold disabled:opacity-50 hover:opacity-85 transition-opacity cursor-pointer"
            >
              {isSavingProfile ? 'Enregistrement...' : 'Enregistrer le profil'}
            </button>
          </div>
        </form>
      </div>

      <hr className="border-border mb-12" />

      {/* Categories Section */}
      <div className="mb-12">
        <div className="flex items-center justify-between mb-6">
          <h1 className="text-xl font-bold text-foreground">Catégories</h1>
          <button
            type="button"
            onClick={openCreateCatModal}
            className="inline-flex items-center justify-center gap-2 px-3 py-2 bg-foreground text-background rounded-lg text-xs font-semibold hover:opacity-80 transition-opacity cursor-pointer shrink-0"
          >
            <Plus className="w-3.5 h-3.5" />
            <span>Nouvelle catégorie</span>
          </button>
        </div>

        {isLoadingCats ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
            {[1, 2, 3].map((n) => (
              <div key={n} className="h-24 bg-background-surface border border-border rounded-xl animate-pulse" />
            ))}
          </div>
        ) : categories.length === 0 ? (
          <p className="text-xs text-foreground-muted py-6">Aucune catégorie définie.</p>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
            {categories.map((cat) => (
              <div
                key={cat.id}
                className="bg-background-surface border border-border rounded-xl p-4 flex flex-col justify-between"
              >
                <div>
                  <div className="flex items-center justify-between gap-2 mb-2">
                    <div className="flex items-center gap-2">
                      <span className="w-2.5 h-2.5 rounded-full shrink-0" style={{ backgroundColor: cat.color }} />
                      <h3 className="font-semibold text-sm text-foreground">{cat.name}</h3>
                    </div>

                    <div className="flex items-center gap-1">
                      <button
                        type="button"
                        onClick={() => openEditCatModal(cat)}
                        className="p-1 text-foreground-muted hover:text-foreground rounded transition-colors"
                        title="Modifier"
                      >
                        <Edit2 className="w-3.5 h-3.5" />
                      </button>
                      <button
                        type="button"
                        onClick={() => handleCatDelete(cat.id, cat.name)}
                        className="p-1 text-foreground-muted hover:text-red-400 rounded transition-colors"
                        title="Supprimer"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    </div>
                  </div>
                  <p className="text-xs text-foreground-muted line-clamp-2">
                    {cat.description || 'Pas de description.'}
                  </p>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <hr className="border-border mb-12" />

      {/* Tags Section */}
      <div>
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
          <h1 className="text-xl font-bold text-foreground">Tags</h1>
          <form onSubmit={handleTagSubmit} className="flex items-center gap-2">
            <input
              type="text"
              value={newTagName}
              onChange={(e) => setNewTagName(e.target.value)}
              placeholder="Nouveau tag..."
              className="px-3 py-2 bg-background-surface border border-border rounded-lg text-xs text-foreground placeholder:text-foreground-subtle focus:outline-none focus:border-foreground/30 transition-colors w-44"
            />
            <button
              type="submit"
              disabled={isSavingTag || !newTagName.trim()}
              className="inline-flex items-center gap-1 px-3 py-2 bg-foreground text-background rounded-lg text-xs font-semibold disabled:opacity-50 hover:opacity-80 transition-opacity cursor-pointer shrink-0"
            >
              <Plus className="w-3.5 h-3.5" />
              <span>Ajouter</span>
            </button>
          </form>
        </div>

        {isLoadingTags ? (
          <div className="flex flex-wrap gap-2">
            {[1, 2, 3, 4, 5].map((n) => (
              <div key={n} className="w-16 h-8 bg-background-surface border border-border rounded-lg animate-pulse" />
            ))}
          </div>
        ) : tags.length === 0 ? (
          <p className="text-xs text-foreground-muted py-6">Aucun tag défini.</p>
        ) : (
          <div className="flex flex-wrap gap-1.5">
            {tags.map((t) => (
              <div
                key={t.id}
                className="inline-flex items-center bg-background-surface border border-border px-2.5 py-1 rounded-lg text-xs font-mono text-foreground-muted hover:border-foreground/20 transition-colors"
              >
                #{t.name}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Category Modal */}
      {isCatModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80">
          <div className="w-full max-w-sm bg-background-surface border border-border rounded-xl p-6 shadow-xl">
            <h2 className="text-sm font-bold text-foreground mb-4">
              {editingCategory ? 'Modifier la catégorie' : 'Créer une catégorie'}
            </h2>

            <form onSubmit={handleCatSubmit} className="space-y-4">
              <div>
                <label className="block text-xs font-semibold text-foreground-muted mb-1">
                  Nom
                </label>
                <input
                  type="text"
                  required
                  value={catName}
                  onChange={(e) => setCatName(e.target.value)}
                  placeholder="ex: Design, Travail, Personnel"
                  className="w-full px-3 py-2 bg-background border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-foreground/30 transition-colors"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-foreground-muted mb-1">
                  Couleur
                </label>
                <div className="flex items-center gap-2">
                  <input
                    type="color"
                    value={catColor}
                    onChange={(e) => setCatColor(e.target.value)}
                    className="w-8 h-8 rounded border border-border cursor-pointer bg-transparent"
                  />
                  <input
                    type="text"
                    value={catColor}
                    onChange={(e) => setCatColor(e.target.value)}
                    className="flex-1 px-3 py-2 bg-background border border-border rounded-lg text-xs font-mono text-foreground focus:outline-none focus:border-foreground/30"
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-semibold text-foreground-muted mb-1">
                  Description
                </label>
                <textarea
                  rows={2}
                  value={catDescription}
                  onChange={(e) => setCatDescription(e.target.value)}
                  placeholder="Description optionnelle..."
                  className="w-full px-3 py-2 bg-background border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-foreground/30 resize-none transition-colors"
                />
              </div>

              <div className="flex items-center justify-end gap-2 pt-4 border-t border-border">
                <button
                  type="button"
                  onClick={() => setIsCatModalOpen(false)}
                  className="px-4 py-2 rounded-lg text-xs font-medium text-foreground-muted hover:text-foreground hover:bg-background-hover cursor-pointer"
                >
                  Annuler
                </button>
                <button
                  type="submit"
                  disabled={isSavingCat || !catName.trim()}
                  className="px-4 py-2 bg-foreground text-background rounded-lg text-xs font-semibold disabled:opacity-50 cursor-pointer"
                >
                  {isSavingCat ? 'Enregistrement...' : 'Enregistrer'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};
