export interface SearchQueryParams {
  q?: string;
  tag?: string;
  tags?: string | string[];
  cat?: string;
  category?: string;
  type?: string;
  contentType?: string;
  by?: string;
  author?: string;
  from?: number | string;
  after?: number | string;
  to?: number | string;
  before?: number | string;
  space?: 'personal' | 'shared' | 'all';
  limit?: number;
  offset?: number;
}

export interface MatchedBlockPreview {
  id: string;
  type: string;
  preview: string;
}

export interface SearchResultItem {
  id: string;
  title: string;
  description: string;
  category?: string | { id: string; name: string; color?: string } | null;
  categoryId?: string | null;
  tags: string[] | Array<{ id: string; name: string }>;
  space: 'personal' | 'shared';
  owner?: { id: string; name: string; email: string };
  author?: string | { id: string; name: string };
  matchScore: number;
  matchedBlocks?: MatchedBlockPreview[];
  createdAt?: string | number | Date;
  updatedAt: string | number | Date;
}

export interface SearchResponse {
  query: string;
  total: number;
  limit: number;
  offset: number;
  results: SearchResultItem[];
}

export interface TagSuggestion {
  tag: string;
  score: number;
  reason: string;
}

export interface ConnectionSuggestion {
  id: string;
  sourceProjectId: string;
  targetProjectId: string;
  sourceProjectTitle: string;
  targetProjectTitle: string;
  score: number;
  reason: string;
  status: 'suggested' | 'accepted' | 'dismissed';
  breakdown?: {
    text: number;
    tag: number;
    cat: number;
    time: number;
    adamicAdar?: number;
  };
  createdAt?: string | number | Date;
}

export const searchApi = {
  search: (params: SearchQueryParams) => {
    const query = new URLSearchParams();
    Object.entries(params).forEach(([key, value]) => {
      if (value !== undefined && value !== null && value !== '') {
        if (Array.isArray(value)) {
          query.set(key, value.join(','));
        } else {
          query.set(key, String(value));
        }
      }
    });
    return api.get<SearchResponse>(`/api/search?${query.toString()}`);
  },
};

export const discoveryApi = {
  getSuggestedTags: (projectId: string) =>
    api.get<{ suggestions: TagSuggestion[] }>(`/api/discovery/suggested-tags/${projectId}`),
  getSuggestedConnections: (projectId?: string) => {
    const url = projectId
      ? `/api/discovery/suggested-connections?projectId=${projectId}`
      : '/api/discovery/suggested-connections';
    return api.get<{ suggestions: ConnectionSuggestion[] }>(url);
  },
  acceptConnection: (connectionId: string) =>
    api.post<{ success: boolean; connection: any }>(`/api/discovery/connections/${connectionId}/accept`),
  dismissConnection: (connectionId: string) =>
    api.post<{ success: boolean; connection: any }>(`/api/discovery/connections/${connectionId}/dismiss`),
};

export const graphApi = {
  getGlobalGraph: (params?: { space?: string; categoryId?: string; tag?: string }) => {
    const query = new URLSearchParams();
    if (params?.space) query.set('space', params.space);
    if (params?.categoryId) query.set('categoryId', params.categoryId);
    if (params?.tag) query.set('tag', params.tag);
    const qs = query.toString();
    return api.get<GlobalGraphData>(`/api/graph/global${qs ? `?${qs}` : ''}`);
  },
  getContextualGraph: (projectId: string) =>
    api.get<ContextualGraphData>(`/api/graph/contextual/${projectId}`),
};

