export const calendarApi = {
  getEvents: (params?: {
    start?: string;
    end?: string;
    from?: string;
    to?: string;
    projectId?: string;
    categoryId?: string;
  }) => {
    const query = new URLSearchParams();
    if (params?.start) query.set('start', params.start);
    if (params?.from) query.set('from', params.from);
    if (params?.end) query.set('end', params.end);
    if (params?.to) query.set('to', params.to);
    if (params?.projectId) query.set('projectId', params.projectId);
    if (params?.categoryId) query.set('categoryId', params.categoryId);
    const qs = query.toString();
    return api.get<{ events: CalendarEvent[] }>(`/api/calendar/events${qs ? `?${qs}` : ''}`);
  },
  createEvent: (data: CreateCalendarEventPayload) =>
    api.post<{ event: CalendarEvent }>('/api/calendar/events', data),
  updateEvent: (eventId: string, data: UpdateCalendarEventPayload) =>
    api.patch<{ event: CalendarEvent }>(`/api/calendar/events/${eventId}`, data),
  deleteEvent: (eventId: string) =>
    api.delete<{ message: string }>(`/api/calendar/events/${eventId}`),
};

export const portabilityApi = {
  exportMarkdown: async (projectId: string): Promise<string> => {
    const token = typeof localStorage !== 'undefined' ? localStorage.getItem('gb_token') : null;
    const headers: Record<string, string> = {};
    if (token) headers['Authorization'] = `Bearer ${token}`;
    const res = await fetch(`/api/projects/${projectId}/export/markdown`, {
      headers,
      credentials: 'include',
    });
    if (!res.ok) throw new ApiError('Failed to export markdown', res.status);
    return res.text();
  },
  importMarkdown: (data: { markdown: string; space?: 'personal' | 'shared'; categoryId?: string | null }) =>
    api.post<{ project: any; blocks: any[]; message: string }>('/api/projects/import/markdown', data),
};


