import React, { useState, useRef, useEffect } from 'react';
import type { MediaBlockContent, MediaType } from '../../../types/block.js';
import {
  Music,
  Image as ImageIcon,
  FileText,
  Video as VideoIcon,
  Play,
  Pause,
  Volume2,
  VolumeX,
  ExternalLink,
  Maximize2,
  X,
  Upload,
  Link as LinkIcon,
  Download,
} from 'lucide-react';

interface MediaBlockProps {
  content: MediaBlockContent;
  onChange: (content: MediaBlockContent) => void;
  readOnly?: boolean;
  isToolbarVisible?: boolean;
}

export const MediaBlock: React.FC<MediaBlockProps> = ({
  content,
  onChange,
  readOnly = false,
  isToolbarVisible = true,
}) => {
  const mediaType = content.mediaType || 'audio';
  const url = content.url || '';
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(content.duration || 0);
  const [volume, setVolume] = useState(0.8);
  const [isMuted, setIsMuted] = useState(false);
  const [lightboxOpen, setLightboxOpen] = useState(false);
  const [isEditingUrl, setIsEditingUrl] = useState(!content.url);
  const [inputUrl, setInputUrl] = useState(content.url || '');
  const [inputTitle, setInputTitle] = useState(content.title || '');
  const [inputCaption, setInputCaption] = useState(content.caption || '');

  const audioRef = useRef<HTMLAudioElement | null>(null);

  const waveformPeaks = React.useMemo(() => {
    if (content.peaks && content.peaks.length > 0) return content.peaks;
    const bars: number[] = [];
    for (let i = 0; i < 48; i++) {
      const v = Math.sin(i * 0.3) * 0.4 + Math.cos(i * 0.7) * 0.3 + 0.5;
      bars.push(Math.max(0.15, Math.min(1.0, v)));
    }
    return bars;
  }, [content.peaks]);

  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;

    const onTimeUpdate = () => setCurrentTime(audio.currentTime);
    const onLoadedMetadata = () => {
      if (audio.duration && !isNaN(audio.duration)) {
        setDuration(audio.duration);
        if (!content.duration) {
          onChange({ ...content, duration: audio.duration });
        }
      }
    };
    const onEnded = () => setIsPlaying(false);

    audio.addEventListener('timeupdate', onTimeUpdate);
    audio.addEventListener('loadedmetadata', onLoadedMetadata);
    audio.addEventListener('ended', onEnded);

    return () => {
      audio.removeEventListener('timeupdate', onTimeUpdate);
      audio.removeEventListener('loadedmetadata', onLoadedMetadata);
      audio.removeEventListener('ended', onEnded);
    };
  }, [content, onChange]);

  const togglePlay = () => {
    const audio = audioRef.current;
    if (!audio) return;
    if (isPlaying) {
      audio.pause();
      setIsPlaying(false);
    } else {
      audio.play().catch(() => {});
      setIsPlaying(true);
    }
  };

  const handleSeek = (percentage: number) => {
    const audio = audioRef.current;
    if (!audio || duration === 0) return;
    const target = percentage * duration;
    audio.currentTime = target;
    setCurrentTime(target);
  };

  const handleVolumeChange = (v: number) => {
    setVolume(v);
    if (audioRef.current) {
      audioRef.current.volume = v;
      setIsMuted(v === 0);
    }
  };

  const toggleMute = () => {
    if (!audioRef.current) return;
    if (isMuted) {
      audioRef.current.volume = volume || 0.5;
      setIsMuted(false);
    } else {
      audioRef.current.volume = 0;
      setIsMuted(true);
    }
  };

  const formatTime = (seconds: number) => {
    if (isNaN(seconds) || seconds < 0) return '0:00';
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
  };

  const handleSaveConfig = () => {
    let detectedType: MediaType = mediaType;
    const lower = inputUrl.toLowerCase();
    if (
      lower.endsWith('.mp3') ||
      lower.endsWith('.wav') ||
      lower.endsWith('.ogg') ||
      lower.endsWith('.m4a') ||
      lower.endsWith('.flac') ||
      lower.startsWith('data:audio/')
    ) {
      detectedType = 'audio';
    } else if (
      lower.endsWith('.png') ||
      lower.endsWith('.jpg') ||
      lower.endsWith('.jpeg') ||
      lower.endsWith('.webp') ||
      lower.endsWith('.gif') ||
      lower.endsWith('.svg') ||
      lower.startsWith('data:image/')
    ) {
      detectedType = 'image';
    } else if (lower.endsWith('.pdf') || lower.startsWith('data:application/pdf')) {
      detectedType = 'pdf';
    } else if (
      lower.endsWith('.mp4') ||
      lower.endsWith('.webm') ||
      lower.endsWith('.mov') ||
      lower.startsWith('data:video/')
    ) {
      detectedType = 'video';
    }

    onChange({
      ...content,
      url: inputUrl,
      mediaType: detectedType,
      title: inputTitle || (inputUrl ? inputUrl.split('/').pop() : undefined),
      caption: inputCaption || undefined,
    });
    setIsEditingUrl(false);
  };

  const handleTypeChange = (type: MediaType) => {
    if (readOnly) return;
    onChange({ ...content, mediaType: type });
  };

  return (
    <div className="w-full rounded-xl overflow-hidden flex flex-col transition-all">
      {/* Media Type Bar & Actions - visible on hover/focus */}
      {isToolbarVisible && (
        <div className="flex items-center justify-between p-2.5 bg-background-surface border border-border rounded-t-xl text-foreground-muted select-none animate-in fade-in duration-150">
          <div className="flex items-center gap-2">
            {mediaType === 'audio' && <Music className="w-4 h-4 text-pink-400" />}
            {mediaType === 'image' && <ImageIcon className="w-4 h-4 text-emerald-400" />}
            {mediaType === 'pdf' && <FileText className="w-4 h-4 text-amber-400" />}
            {mediaType === 'video' && <VideoIcon className="w-4 h-4 text-sky-400" />}
            <span className="font-mono text-xs font-bold uppercase tracking-wider text-foreground">
              Bloc {mediaType}
            </span>
          </div>

          {!readOnly && (
            <div className="flex items-center gap-1.5">
              <div className="flex items-center bg-background rounded-lg p-0.5 border border-border text-xs">
                <button
                  type="button"
                  onClick={() => handleTypeChange('audio')}
                  className={`px-2.5 py-1 min-h-[36px] rounded-md font-mono transition-colors cursor-pointer ${
                    mediaType === 'audio' ? 'bg-accent text-accent-foreground font-semibold' : 'hover:text-foreground'
                  }`}
                >
                  Audio
                </button>
                <button
                  type="button"
                  onClick={() => handleTypeChange('image')}
                  className={`px-2.5 py-1 min-h-[36px] rounded-md font-mono transition-colors cursor-pointer ${
                    mediaType === 'image' ? 'bg-accent text-accent-foreground font-semibold' : 'hover:text-foreground'
                  }`}
                >
                  Image
                </button>
                <button
                  type="button"
                  onClick={() => handleTypeChange('pdf')}
                  className={`px-2.5 py-1 min-h-[36px] rounded-md font-mono transition-colors cursor-pointer ${
                    mediaType === 'pdf' ? 'bg-accent text-accent-foreground font-semibold' : 'hover:text-foreground'
                  }`}
                >
                  PDF
                </button>
                <button
                  type="button"
                  onClick={() => handleTypeChange('video')}
                  className={`px-2.5 py-1 min-h-[36px] rounded-md font-mono transition-colors cursor-pointer ${
                    mediaType === 'video' ? 'bg-accent text-accent-foreground font-semibold' : 'hover:text-foreground'
                  }`}
                >
                  Vidéo
                </button>
              </div>

              <button
                type="button"
                onClick={() => setIsEditingUrl(!isEditingUrl)}
                className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg hover:bg-background-hover hover:text-foreground text-xs font-mono transition-colors cursor-pointer"
                title="Modifier l'URL / fichier"
              >
                <LinkIcon className="w-4 h-4" />
              </button>
            </div>
          )}
        </div>
      )}

      {/* URL & Metadata Config Drawer */}
      {isEditingUrl && !readOnly && isToolbarVisible && (
        <div className="p-3 bg-background-surface/90 border-x border-b border-border space-y-2 animate-in fade-in">
          <div className="flex gap-2">
            <input
              type="text"
              value={inputUrl}
              onChange={(e) => setInputUrl(e.target.value)}
              placeholder="URL ou chemin du média (e.g. /audio.mp3, https://example.com/art.png, data:...)"
              className="flex-1 px-3 py-2 bg-background border border-border rounded-lg text-sm text-foreground focus:outline-none focus:ring-1 focus:ring-accent font-mono min-h-[44px]"
            />
            <button
              type="button"
              onClick={handleSaveConfig}
              className="px-4 py-2 min-h-[44px] bg-accent text-accent-foreground text-xs font-bold rounded-lg hover:opacity-90 transition-opacity cursor-pointer"
            >
              Enregistrer
            </button>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
            <input
              type="text"
              value={inputTitle}
              onChange={(e) => setInputTitle(e.target.value)}
              placeholder="Titre du fichier"
              className="px-3 py-2 min-h-[44px] bg-background border border-border rounded-lg text-sm text-foreground focus:outline-none"
            />
            <input
              type="text"
              value={inputCaption}
              onChange={(e) => setInputCaption(e.target.value)}
              placeholder="Légende / Notes"
              className="px-3 py-2 min-h-[44px] bg-background border border-border rounded-lg text-sm text-foreground focus:outline-none"
            />
          </div>
        </div>
      )}

      {/* Media Player / Viewer Body */}
      <div className={`p-4 ${isToolbarVisible ? 'border-x border-b border-border rounded-b-xl bg-card/40' : ''}`}>
        {!url ? (
          <div className="py-8 text-center border-2 border-dashed border-border rounded-xl p-6 bg-background/30">
            <Upload className="w-8 h-8 mx-auto text-foreground-muted mb-2 animate-pulse" />
            <p className="text-sm font-mono text-foreground font-semibold">Aucun média attaché</p>
            <p className="text-xs text-foreground-muted mt-1 max-w-sm mx-auto">
              Glissez un fichier directement sur la page ou spécifiez une URL ci-dessus.
            </p>
            {!readOnly && !isEditingUrl && (
              <button
                type="button"
                onClick={() => setIsEditingUrl(true)}
                className="mt-3 px-4 py-2 min-h-[44px] bg-accent text-accent-foreground text-xs font-bold rounded-lg cursor-pointer"
              >
                Configurer le média
              </button>
            )}
          </div>
        ) : (
          <>
            {/* 1. AUDIO PLAYER */}
            {mediaType === 'audio' && (
              <div className="space-y-3">
                <audio ref={audioRef} src={url} preload="metadata" />

                <div className="flex items-center justify-between">
                  <div>
                    <h4 className="font-bold text-base text-foreground">{content.title || 'Piste audio'}</h4>
                    {content.caption && <p className="text-xs text-foreground-muted">{content.caption}</p>}
                  </div>
                  <span className="font-mono text-xs text-foreground-muted">
                    {formatTime(currentTime)} / {formatTime(duration)}
                  </span>
                </div>

                {/* Waveform Visualization */}
                <div
                  onClick={(e) => {
                    const rect = e.currentTarget.getBoundingClientRect();
                    const clickX = e.clientX - rect.left;
                    handleSeek(Math.max(0, Math.min(1, clickX / rect.width)));
                  }}
                  className="h-16 bg-background/80 rounded-xl p-2.5 flex items-center gap-1 cursor-pointer border border-border hover:border-accent/50 transition-colors"
                >
                  {waveformPeaks.map((peak, idx) => {
                    const barProgress = idx / waveformPeaks.length;
                    const isPlayed = duration > 0 && currentTime / duration >= barProgress;
                    const heightPercent = Math.max(15, Math.round(peak * 100));

                    return (
                      <div
                        key={idx}
                        className="flex-1 flex items-center justify-center h-full group"
                      >
                        <div
                          className={`w-full rounded-full transition-all duration-75 ${
                            isPlayed
                              ? 'bg-accent shadow-[0_0_8px_rgba(255,222,89,0.5)]'
                              : 'bg-border group-hover:bg-foreground-muted'
                          } border-border`}
                          style={{ height: `${heightPercent}%` }}
                        />
                      </div>
                    );
                  })}
                </div>

                {/* Controls Bar */}
                <div className="flex items-center justify-between pt-1">
                  <div className="flex items-center gap-3">
                    <button
                      type="button"
                      onClick={togglePlay}
                      className="w-11 h-11 rounded-full bg-accent text-accent-foreground flex items-center justify-center hover:scale-105 transition-transform cursor-pointer shadow-md"
                      title={isPlaying ? 'Pause' : 'Play'}
                    >
                      {isPlaying ? <Pause className="w-5 h-5 fill-current" /> : <Play className="w-5 h-5 fill-current ml-0.5" />}
                    </button>
                    <span className="font-mono text-xs font-semibold text-foreground">
                      {isPlaying ? 'LECTURE' : 'PAUSE'}
                    </span>
                  </div>

                  <div className="flex items-center gap-2">
                    <button
                      type="button"
                      onClick={toggleMute}
                      className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg text-foreground-muted hover:text-foreground cursor-pointer"
                    >
                      {isMuted ? <VolumeX className="w-5 h-5 text-destructive" /> : <Volume2 className="w-5 h-5" />}
                    </button>
                    <input
                      type="range"
                      min="0"
                      max="1"
                      step="0.05"
                      value={isMuted ? 0 : volume}
                      onChange={(e) => handleVolumeChange(parseFloat(e.target.value))}
                      className="w-24 accent-accent h-2 bg-background rounded-lg cursor-pointer"
                    />
                  </div>
                </div>
              </div>
            )}

            {/* 2. IMAGE VIEWER */}
            {mediaType === 'image' && (
              <div className="space-y-2">
                <div className="relative group rounded-xl overflow-hidden border border-border bg-background/50 flex items-center justify-center max-h-[500px]">
                  <img
                    src={url}
                    alt={content.alt || content.title || 'Attached Artwork'}
                    className="w-full h-auto max-h-[500px] object-contain rounded-xl transition-transform"
                  />
                  <button
                    type="button"
                    onClick={() => setLightboxOpen(true)}
                    className="absolute top-3 right-3 p-2 min-h-[44px] min-w-[44px] flex items-center justify-center bg-background/80 backdrop-blur rounded-lg text-foreground opacity-0 group-hover:opacity-100 transition-opacity hover:bg-background cursor-pointer"
                    title="Agrandir en plein écran"
                  >
                    <Maximize2 className="w-4 h-4" />
                  </button>
                </div>
                {(content.title || content.caption) && (
                  <div className="text-xs text-foreground-muted pt-1">
                    {content.title && <span className="font-semibold text-foreground mr-2 text-sm">{content.title}</span>}
                    {content.caption && <span>{content.caption}</span>}
                  </div>
                )}
              </div>
            )}

            {/* 3. PDF PREVIEW */}
            {mediaType === 'pdf' && (
              <div className="flex items-center justify-between p-4 bg-background-surface border border-border rounded-xl">
                <div className="flex items-center gap-3.5">
                  <div className="w-12 h-12 rounded-xl bg-amber-500/10 border border-amber-500/30 flex items-center justify-center text-amber-400 font-bold text-sm font-mono">
                    PDF
                  </div>
                  <div>
                    <h4 className="font-semibold text-base text-foreground">
                      {content.title || content.fileName || 'Document.pdf'}
                    </h4>
                    <p className="text-xs text-foreground-muted">
                      {content.sizeBytes ? `${Math.round(content.sizeBytes / 1024)} KB` : 'Document PDF'}
                    </p>
                  </div>
                </div>
                <a
                  href={url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="flex items-center gap-2 px-4 py-2.5 min-h-[44px] bg-background hover:bg-background-hover border border-border rounded-lg text-xs font-mono font-semibold text-foreground transition-colors cursor-pointer"
                >
                  <span>Ouvrir PDF</span>
                  <ExternalLink className="w-4 h-4" />
                </a>
              </div>
            )}

            {/* 4. VIDEO PLAYER */}
            {mediaType === 'video' && (
              <div className="space-y-2">
                <div className="rounded-xl overflow-hidden border border-border bg-black">
                  <video
                    src={url}
                    controls
                    className="w-full max-h-[480px] rounded-xl object-contain bg-black"
                  />
                </div>
                {(content.title || content.caption) && (
                  <div className="text-xs text-foreground-muted pt-1">
                    {content.title && <span className="font-semibold text-foreground mr-2 text-sm">{content.title}</span>}
                    {content.caption && <span>{content.caption}</span>}
                  </div>
                )}
              </div>
            )}
          </>
        )}
      </div>

      {/* Lightbox Modal */}
      {lightboxOpen && (
        <div
          className="fixed inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4"
          onClick={() => setLightboxOpen(false)}
        >
          <button
            type="button"
            onClick={() => setLightboxOpen(false)}
            className="absolute top-4 right-4 p-2.5 min-h-[44px] min-w-[44px] flex items-center justify-center text-white hover:text-accent rounded-full bg-background-surface/70 cursor-pointer"
          >
            <X className="w-6 h-6" />
          </button>
          <img
            src={url}
            alt={content.alt || 'Expanded view'}
            className="max-w-[90vw] max-h-[90vh] object-contain rounded-xl border border-border"
            onClick={(e) => e.stopPropagation()}
          />
        </div>
      )}
    </div>
  );
};
