import React, { useRef, useState, useEffect, useCallback } from 'react';
import type { DrawingBlockContent, DrawingStroke } from '../../../types/block.js';
import {
  PenTool,
  Eraser,
  Undo2,
  Redo2,
  Trash2,
  Download,
} from 'lucide-react';

interface DrawingBlockProps {
  content: DrawingBlockContent;
  onChange: (content: DrawingBlockContent) => void;
  readOnly?: boolean;
  isToolbarVisible?: boolean;
}

const COLOR_PRESETS = [
  { name: 'Studio Gold', hex: '#FFDE59' },
  { name: 'Neon Cyan', hex: '#00F0FF' },
  { name: 'Coral Pink', hex: '#FF5376' },
  { name: 'Pure White', hex: '#FFFFFF' },
  { name: 'Electric Violet', hex: '#818cf8' },
  { name: 'Charcoal Black', hex: '#18181b' },
];

const STROKE_WIDTHS = [
  { label: 'Fine', value: 2 },
  { label: 'Normal', value: 4 },
  { label: 'Thick', value: 8 },
  { label: 'Broad', value: 16 },
];

export const DrawingBlock: React.FC<DrawingBlockProps> = ({
  content,
  onChange,
  readOnly = false,
  isToolbarVisible = true,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [selectedColor, setSelectedColor] = useState<string>('#FFDE59');
  const [strokeWidth, setStrokeWidth] = useState<number>(4);
  const [isEraser, setIsEraser] = useState<boolean>(false);
  const [isDrawing, setIsDrawing] = useState<boolean>(false);

  // Undo / Redo history
  const [strokes, setStrokes] = useState<DrawingStroke[]>(content.strokes || []);
  const [redoStack, setRedoStack] = useState<DrawingStroke[][]>([]);
  const currentStrokeRef = useRef<Array<[number, number, number?]>>([]);

  useEffect(() => {
    if (content.strokes && content.strokes !== strokes) {
      setStrokes(content.strokes);
    }
  }, [content.strokes]);

  const redrawCanvas = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    for (const stroke of strokes) {
      if (!stroke.points || stroke.points.length === 0) continue;

      ctx.save();
      ctx.lineWidth = stroke.width;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      if (stroke.isEraser) {
        ctx.globalCompositeOperation = 'destination-out';
        ctx.strokeStyle = 'rgba(0,0,0,1)';
      } else {
        ctx.globalCompositeOperation = 'source-over';
        ctx.strokeStyle = stroke.color;
      }

      ctx.beginPath();
      const points = stroke.points;
      ctx.moveTo(points[0][0], points[0][1]);

      if (points.length === 1) {
        ctx.arc(points[0][0], points[0][1], stroke.width / 2, 0, Math.PI * 2);
        ctx.fillStyle = stroke.isEraser ? 'rgba(0,0,0,1)' : stroke.color;
        ctx.fill();
      } else if (points.length === 2) {
        ctx.lineTo(points[1][0], points[1][1]);
        ctx.stroke();
      } else {
        for (let i = 1; i < points.length - 1; i++) {
          const xc = (points[i][0] + points[i + 1][0]) / 2;
          const yc = (points[i][1] + points[i + 1][1]) / 2;
          ctx.quadraticCurveTo(points[i][0], points[i][1], xc, yc);
        }
        ctx.lineTo(points[points.length - 1][0], points[points.length - 1][1]);
        ctx.stroke();
      }

      ctx.restore();
    }
  }, [strokes]);

  useEffect(() => {
    redrawCanvas();
  }, [redrawCanvas]);

  const getCanvasCoordinates = (e: React.MouseEvent | React.TouchEvent | MouseEvent | TouchEvent): [number, number] | null => {
    const canvas = canvasRef.current;
    if (!canvas) return null;
    const rect = canvas.getBoundingClientRect();
    const clientX = 'touches' in e ? e.touches[0].clientX : (e as MouseEvent).clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : (e as MouseEvent).clientY;
    return [clientX - rect.left, clientY - rect.top];
  };

  const startDrawing = (e: React.MouseEvent<HTMLCanvasElement> | React.TouchEvent<HTMLCanvasElement>) => {
    if (readOnly) return;
    const coords = getCanvasCoordinates(e.nativeEvent);
    if (!coords) return;

    setIsDrawing(true);
    currentStrokeRef.current = [coords];
  };

  const drawMove = (e: React.MouseEvent<HTMLCanvasElement> | React.TouchEvent<HTMLCanvasElement>) => {
    if (!isDrawing || readOnly) return;
    const coords = getCanvasCoordinates(e.nativeEvent);
    if (!coords) return;

    currentStrokeRef.current.push(coords);

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const points = currentStrokeRef.current;
    if (points.length < 2) return;

    ctx.save();
    ctx.lineWidth = strokeWidth;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    if (isEraser) {
      ctx.globalCompositeOperation = 'destination-out';
      ctx.strokeStyle = 'rgba(0,0,0,1)';
    } else {
      ctx.globalCompositeOperation = 'source-over';
      ctx.strokeStyle = selectedColor;
    }

    ctx.beginPath();
    const p1 = points[points.length - 2];
    const p2 = points[points.length - 1];
    ctx.moveTo(p1[0], p1[1]);
    ctx.lineTo(p2[0], p2[1]);
    ctx.stroke();
    ctx.restore();
  };

  const endDrawing = () => {
    if (!isDrawing || readOnly) return;
    setIsDrawing(false);

    if (currentStrokeRef.current.length > 0) {
      const newStroke: DrawingStroke = {
        color: selectedColor,
        width: strokeWidth,
        points: [...currentStrokeRef.current],
        isEraser,
      };

      const updatedStrokes = [...strokes, newStroke];
      setStrokes(updatedStrokes);
      setRedoStack([]);

      const canvas = canvasRef.current;
      const dataUrl = canvas ? canvas.toDataURL('image/png') : undefined;
      onChange({ strokes: updatedStrokes, dataUrl });
    }

    currentStrokeRef.current = [];
  };

  const handleUndo = () => {
    if (strokes.length === 0 || readOnly) return;
    const previousStrokes = strokes.slice(0, strokes.length - 1);
    const poppedStroke = strokes[strokes.length - 1];

    setRedoStack((prev) => [[poppedStroke], ...prev]);
    setStrokes(previousStrokes);

    const canvas = canvasRef.current;
    const dataUrl = canvas ? canvas.toDataURL('image/png') : undefined;
    onChange({ strokes: previousStrokes, dataUrl });
  };

  const handleRedo = () => {
    if (redoStack.length === 0 || readOnly) return;
    const [nextStrokes, ...remainingRedo] = redoStack;
    const updatedStrokes = [...strokes, ...nextStrokes];

    setRedoStack(remainingRedo);
    setStrokes(updatedStrokes);

    const canvas = canvasRef.current;
    const dataUrl = canvas ? canvas.toDataURL('image/png') : undefined;
    onChange({ strokes: updatedStrokes, dataUrl });
  };

  const handleClear = () => {
    if (readOnly) return;
    if (strokes.length === 0) return;
    if (window.confirm('Effacer tout le dessin ?')) {
      setStrokes([]);
      setRedoStack([]);
      onChange({ strokes: [], dataUrl: '' });
    }
  };

  const handleExportPng = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const link = document.createElement('a');
    link.download = `dessin-${Date.now()}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
  };

  return (
    <div className="w-full rounded-xl overflow-hidden flex flex-col transition-all">
      {/* Control Toolbar */}
      {!readOnly && isToolbarVisible && (
        <div className="flex flex-wrap items-center justify-between gap-2 p-2 bg-background-surface border border-border rounded-t-xl text-foreground-muted select-none animate-in fade-in duration-150">
          {/* Mode & Tools */}
          <div className="flex items-center gap-1">
            <button
              type="button"
              onClick={() => setIsEraser(false)}
              className={`p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg transition-colors cursor-pointer ${
                !isEraser ? 'bg-accent text-accent-foreground font-semibold shadow-sm' : 'hover:bg-background-hover hover:text-foreground'
              }`}
              title="Stylo"
            >
              <PenTool className="w-4 h-4" />
            </button>
            <button
              type="button"
              onClick={() => setIsEraser(true)}
              className={`p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg transition-colors cursor-pointer ${
                isEraser ? 'bg-accent text-accent-foreground font-semibold shadow-sm' : 'hover:bg-background-hover hover:text-foreground'
              }`}
              title="Gomme"
            >
              <Eraser className="w-4 h-4" />
            </button>

            <div className="w-px h-6 bg-border mx-1 border-border" />

            {/* Colors */}
            {!isEraser && (
              <div className="flex items-center gap-1.5">
                {COLOR_PRESETS.map((preset) => (
                  <button
                    key={preset.hex}
                    type="button"
                    onClick={() => setSelectedColor(preset.hex)}
                    title={preset.name}
                    className={`w-7 h-7 rounded-full border border-border transition-transform cursor-pointer ${
                      selectedColor === preset.hex ? 'scale-110 ring-2 ring-accent' : 'hover:scale-105'
                    }`}
                    style={{ backgroundColor: preset.hex }}
                  />
                ))}
              </div>
            )}

            <div className="w-px h-6 bg-border mx-1 border-border" />

            {/* Stroke Width */}
            <div className="flex items-center gap-1 bg-background rounded-lg p-1 border border-border">
              {STROKE_WIDTHS.map((sw) => (
                <button
                  key={sw.value}
                  type="button"
                  onClick={() => setStrokeWidth(sw.value)}
                  className={`px-2.5 py-1 min-h-[36px] text-xs font-mono rounded-md transition-colors cursor-pointer ${
                    strokeWidth === sw.value ? 'bg-accent text-accent-foreground font-bold' : 'hover:text-foreground'
                  }`}
                  title={`${sw.label} (${sw.value}px)`}
                >
                  {sw.value}px
                </button>
              ))}
            </div>
          </div>

          {/* Action buttons */}
          <div className="flex items-center gap-1">
            <button
              type="button"
              onClick={handleUndo}
              disabled={strokes.length === 0}
              className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg hover:bg-background-hover hover:text-foreground disabled:opacity-30 disabled:cursor-not-allowed transition-colors cursor-pointer"
              title="Annuler"
            >
              <Undo2 className="w-4 h-4" />
            </button>
            <button
              type="button"
              onClick={handleRedo}
              disabled={redoStack.length === 0}
              className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg hover:bg-background-hover hover:text-foreground disabled:opacity-30 disabled:cursor-not-allowed transition-colors cursor-pointer"
              title="Rétablir"
            >
              <Redo2 className="w-4 h-4" />
            </button>
            <button
              type="button"
              onClick={handleClear}
              disabled={strokes.length === 0}
              className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg hover:bg-background-hover hover:text-destructive text-foreground-muted disabled:opacity-30 disabled:cursor-not-allowed transition-colors cursor-pointer"
              title="Effacer tout"
            >
              <Trash2 className="w-4 h-4" />
            </button>
            <button
              type="button"
              onClick={handleExportPng}
              className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg hover:bg-background-hover hover:text-foreground transition-colors cursor-pointer"
              title="Exporter en PNG"
            >
              <Download className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}

      {/* Canvas Area */}
      <div className={`relative w-full h-[320px] bg-[#0c0c11] overflow-hidden cursor-crosshair ${
        isToolbarVisible ? 'border-x border-b border-border rounded-b-xl' : 'rounded-xl border border-border/40'
      }`}>
        <canvas
          ref={canvasRef}
          width={800}
          height={320}
          onMouseDown={startDrawing}
          onMouseMove={drawMove}
          onMouseUp={endDrawing}
          onMouseLeave={endDrawing}
          onTouchStart={startDrawing}
          onTouchMove={drawMove}
          onTouchEnd={endDrawing}
          className="w-full h-full touch-none"
        />
        {strokes.length === 0 && !isDrawing && (
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none text-foreground-muted/40 font-mono text-sm">
            <span>Zone de dessin &bull; Dessinez ou esquissez vos idées</span>
          </div>
        )}
      </div>
    </div>
  );
};
