import React, { useState, useEffect, useCallback } from 'react';
import { Tag as TagIcon, Plus, Search } from 'lucide-react';
import type { Tag } from '../../types/project.js';
import { api } from '../../lib/api.js';

export const TagsView: React.FC = () => {
  const [tags, setTags] = useState<Tag[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [newTagName, setNewTagName] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const fetchTags = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const url = searchQuery.trim() ? `/api/tags?q=${encodeURIComponent(searchQuery.trim())}` : '/api/tags';
      const response = await api.get<{ tags: Tag[] }>(url);
      setTags(response.tags);
    } catch (err: any) {
      setError(err.message || 'Failed to load tags');
    } finally {
      setIsLoading(false);
    }
  }, [searchQuery]);

  useEffect(() => {
    fetchTags();
  }, [fetchTags]);

  const handleCreateTag = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTagName.trim()) return;

    setIsSubmitting(true);
    setError(null);
    try {
      await api.post('/api/tags', { name: newTagName.trim() });
      setNewTagName('');
      await fetchTags();
    } catch (err: any) {
      setError(err.message || 'Failed to create tag');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-4 border-b border-border">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold tracking-tight text-foreground flex items-center gap-2" data-testid="tags-title">
            <TagIcon className="w-6 h-6 text-emerald-500" />
            Free-form Tags Index
          </h1>
          <p className="text-xs text-foreground-muted mt-1">
            Organic keywords created by members and used by the discovery engine to surface cross-project connections.
          </p>
        </div>

        <form onSubmit={handleCreateTag} className="flex items-center gap-2">
          <input
            type="text"
            value={newTagName}
            onChange={(e) => setNewTagName(e.target.value)}
            placeholder="Add new tag..."
            data-testid="new-tag-input"
            className="px-3 py-1.5 bg-background-surface border border-border rounded-lg text-xs text-foreground placeholder:text-foreground-subtle focus:outline-none focus:ring-2 focus:ring-accent w-44 sm:w-56"
          />
          <button
            type="submit"
            disabled={isSubmitting || !newTagName.trim()}
            data-testid="add-tag-btn"
            className="inline-flex items-center gap-1 px-3 py-1.5 bg-accent hover:bg-accent-hover text-white rounded-lg text-xs font-semibold tracking-wide disabled:opacity-50 transition-colors shadow-sm cursor-pointer shrink-0"
          >
            <Plus className="w-3.5 h-3.5" />
            <span>Add</span>
          </button>
        </form>
      </div>

      {error && (
        <div className="p-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-400 text-xs" data-testid="tag-error-message">
          {error}
        </div>
      )}

      {/* Search filter bar */}
      <div className="relative max-w-sm">
        <Search className="w-4 h-4 text-foreground-subtle absolute left-3 top-1/2 -translate-y-1/2" />
        <input
          type="text"
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          placeholder="Filter tags..."
          data-testid="filter-tags-input"
          className="w-full pl-9 pr-3 py-1.5 bg-background-surface border border-border rounded-lg text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-accent"
        />
      </div>

      {/* Tags Cloud / Grid */}
      {isLoading ? (
        <div className="flex flex-wrap gap-2">
          {[1, 2, 3, 4, 5, 6].map((n) => (
            <div key={n} className="w-24 h-8 bg-background-surface border border-border rounded-lg animate-pulse" />
          ))}
        </div>
      ) : tags.length === 0 ? (
        <div className="text-center py-12 bg-background-surface border border-dashed border-border rounded-xl p-8">
          <TagIcon className="w-10 h-10 text-foreground-subtle mx-auto mb-3" />
          <h3 className="text-sm font-semibold text-foreground">No tags found</h3>
          <p className="text-xs text-foreground-muted mt-1">
            Create tags above or assign them to projects to build the collective tag graph.
          </p>
        </div>
      ) : (
        <div className="flex flex-wrap gap-2">
          {tags.map((t) => (
            <div
              key={t.id}
              data-testid={`tag-pill-${t.id}`}
              className="inline-flex items-center gap-1.5 bg-background-surface border border-border hover:border-emerald-500/40 px-3 py-1.5 rounded-lg text-xs text-foreground transition-colors shadow-xs"
            >
              <TagIcon className="w-3 h-3 text-emerald-400" />
              <span className="font-medium font-mono">{t.name}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};
