import React, { useEffect, useRef, useState } from 'react';
import type { PresenceUser } from '../../types/block.js';

interface PresenceCursorsProps {
  users: PresenceUser[];
  mode?: 'stack' | 'canvas';
  panX?: number;
  panY?: number;
  zoom?: number;
}

interface InterpolatedCursor {
  currentX: number;
  currentY: number;
  targetX: number;
  targetY: number;
  color: string;
  userName: string;
  lastUpdated: number;
  opacity: number;
}

const LERP_FACTOR = 0.28;
const FADE_TIMEOUT_MS = 3000;

export const PresenceCursors: React.FC<PresenceCursorsProps> = ({
  users,
  mode = 'stack',
  panX = 0,
  panY = 0,
  zoom = 1.0,
}) => {
  const cursorsRef = useRef<Map<string, InterpolatedCursor>>(new Map());
  const [renderedCursors, setRenderedCursors] = useState<Array<{ id: string } & InterpolatedCursor>>([]);
  const animFrameRef = useRef<number | null>(null);

  // Update target coordinates when users prop changes
  useEffect(() => {
    const currentMap = cursorsRef.current;
    const activeIds = new Set(users.map((u) => u.userId));

    // Remove users who left
    for (const id of currentMap.keys()) {
      if (!activeIds.has(id)) {
        currentMap.delete(id);
      }
    }

    for (const user of users) {
      if (!user.cursor) continue;

      let targetX = user.cursor.x;
      let targetY = user.cursor.y;

      // In canvas mode, transform world target coordinate to current screen space
      if (mode === 'canvas') {
        const z = Math.max(0.1, Math.min(3.0, zoom));
        targetX = (targetX + panX) * z;
        targetY = (targetY + panY) * z;
      }

      const existing = currentMap.get(user.userId);
      if (existing) {
        existing.targetX = targetX;
        existing.targetY = targetY;
        existing.lastUpdated = user.lastUpdated || Date.now();
        existing.color = user.color;
        existing.userName = user.userName;
      } else {
        currentMap.set(user.userId, {
          currentX: targetX,
          currentY: targetY,
          targetX,
          targetY,
          color: user.color,
          userName: user.userName,
          lastUpdated: user.lastUpdated || Date.now(),
          opacity: 1.0,
        });
      }
    }

    const immediateList: Array<{ id: string } & InterpolatedCursor> = [];
    for (const [id, cursor] of currentMap.entries()) {
      if (cursor.opacity > 0.01) {
        immediateList.push({ id, ...cursor });
      }
    }
    setRenderedCursors(immediateList);
  }, [users, mode, panX, panY, zoom]);

  // 60 FPS LERP Smoothing Loop
  useEffect(() => {
    let isRunning = true;

    const tick = () => {
      if (!isRunning) return;

      const now = Date.now();
      const updatedList: Array<{ id: string } & InterpolatedCursor> = [];
      const currentMap = cursorsRef.current;

      for (const [id, cursor] of currentMap.entries()) {
        // LERP interpolation
        cursor.currentX += (cursor.targetX - cursor.currentX) * LERP_FACTOR;
        cursor.currentY += (cursor.targetY - cursor.currentY) * LERP_FACTOR;

        // Inactivity fade
        const timeSinceUpdate = now - cursor.lastUpdated;
        if (timeSinceUpdate > FADE_TIMEOUT_MS) {
          cursor.opacity = Math.max(0, cursor.opacity - 0.05);
        } else {
          cursor.opacity = Math.min(1.0, cursor.opacity + 0.1);
        }

        if (cursor.opacity > 0.01) {
          updatedList.push({
            id,
            ...cursor,
          });
        }
      }

      setRenderedCursors(updatedList);
      animFrameRef.current = requestAnimationFrame(tick);
    };

    animFrameRef.current = requestAnimationFrame(tick);

    return () => {
      isRunning = false;
      if (animFrameRef.current) {
        cancelAnimationFrame(animFrameRef.current);
      }
    };
  }, []);

  if (renderedCursors.length === 0) return null;

  return (
    <div className="absolute inset-0 pointer-events-none z-40 overflow-hidden">
      {renderedCursors.map((cursor) => (
        <div
          key={cursor.id}
          className="absolute top-0 left-0 transition-opacity duration-150 ease-out"
          style={{
            transform: `translate3d(${cursor.currentX}px, ${cursor.currentY}px, 0)`,
            opacity: cursor.opacity,
          }}
        >
          {/* Custom SVG Cursor Arrow */}
          <svg
            className="w-5 h-5 -rotate-45 drop-shadow-md"
            viewBox="0 0 24 24"
            fill={cursor.color}
            stroke="#000000"
            strokeWidth="1.5"
          >
            <path d="M3 3l7 18 3-7 7-3L3 3z" />
          </svg>

          {/* User Name Tag Badge */}
          <div
            className="absolute left-4 top-2 px-2 py-0.5 rounded-full text-[10px] font-mono font-bold text-background shadow-lg whitespace-nowrap"
            style={{ backgroundColor: cursor.color }}
          >
            {cursor.userName}
          </div>
        </div>
      ))}
    </div>
  );
};
