import React, { useState } from 'react';
import { useAuth } from './context/AuthContext.js';
import { AppLayout } from './components/layout/AppLayout.js';
import { LoginView } from './components/auth/LoginView.js';
import { RegisterView } from './components/auth/RegisterView.js';
import { ProjectsView } from './components/projects/ProjectsView.js';
import { CategoriesView } from './components/categories/CategoriesView.js';
import { TagsView } from './components/tags/TagsView.js';
import { WebSocketProvider } from './context/WebSocketContext.js';
import { ProjectEditor } from './components/editor/ProjectEditor.js';
import { DashboardView } from './components/dashboard/DashboardView.js';

import { LivingNodalMap } from './components/graph/LivingNodalMap.js';

export const App: React.FC = () => {
  const { isAuthenticated, isLoading } = useAuth();
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [currentView, setCurrentView] = useState<string>('dashboard');
  const [activeProjectId, setActiveProjectId] = useState<string | null>(null);

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background flex flex-col items-center justify-center p-6 text-center">
        <div className="w-10 h-10 border-2 border-foreground border-t-transparent rounded-full animate-spin mb-4" />
        <p className="text-xs text-foreground-muted tracking-widest font-mono">
          OHARA
        </p>
      </div>
    );
  }

  if (!isAuthenticated) {
    if (authMode === 'register') {
      return <RegisterView onSwitchToLogin={() => setAuthMode('login')} />;
    }
    return <LoginView onSwitchToRegister={() => setAuthMode('register')} />;
  }

  const handleNavigate = (view: string, projectId?: string) => {
    setCurrentView(view);
    if (projectId !== undefined) {
      setActiveProjectId(projectId || null);
    }
  };

  return (
    <AppLayout
      currentView={currentView}
      currentProjectId={activeProjectId || undefined}
      onNavigate={handleNavigate}
    >
      {currentView === 'dashboard' && (
        <DashboardView
          onNavigate={handleNavigate}
          onCreateProject={() => handleNavigate('projects')}
        />
      )}
      {currentView === 'projects' && (
        <ProjectsView onNavigate={handleNavigate} />
      )}
      {currentView === 'editor' && activeProjectId && (
        <WebSocketProvider projectId={activeProjectId}>
          <ProjectEditor
            projectId={activeProjectId}
            onBack={() => handleNavigate('projects')}
            onNavigate={handleNavigate}
          />
        </WebSocketProvider>
      )}
      {currentView === 'categories' && <CategoriesView />}
      {currentView === 'tags' && <TagsView />}
      {currentView === 'graph' && (
        <div className="w-full h-full min-h-[calc(100vh-4rem)] flex-1 flex flex-col">
          <LivingNodalMap
            mode="global"
            onNavigate={handleNavigate}
          />
        </div>
      )}
    </AppLayout>
  );
};
export default App;
