/**
 * Living Force-Directed Nodal Map & Constellation Visualizer
 * La Grande Bibliothèque — Milestone 4 (Features F18, F19, F20, F21, F22 & R4)
 * 
 * High-performance 60 FPS HTML5 Canvas component supporting:
 * - Pure force-directed layout (Coulomb, Hooke, Hub gravity, Centering)
 * - Decoupled continuous organic breathing wave superposition
 * - Louvain modularity constellation nebulae with visible theme name labels on translucent pills
 * - Edge hit-testing and hover inspection tooltips with connection reasons
 * - Node click opens right-hand detail drawer panel with connection breakdown
 * - High-contrast readable node typography with background pill backing
 * - Bottom color legend for connection types and top Category/Tag dropdown filters
 * - Global and contextual ego-network modes (with 2-hop ghost nodes)
 * - Affine pan/zoom (0.1x to 3.0x), node dragging, hover glow
 */

import React, { useRef, useEffect, useState, useCallback, useMemo } from 'react';
import type {
  GraphNode,
  GraphEdge,
  CommunityCluster,
  GlobalGraphData,
  ContextualGraphData,
} from '../../types/graph.js';
import { graphApi, tagsApi, categoriesApi } from '../../lib/api.js';
import {
  simulateForceDirectedStep,
  initializeNodePositions,
  type PhysicsSimulationNode,
} from './physicsSimulation.js';
import {
  computeOrganicBreathingOffset,
  affineTransformWorldToScreen,
  affineTransformScreenToWorld,
} from './organicBreathing.js';
import { renderNebulaHull } from './convexHull.js';
import { GraphToolbar } from './GraphToolbar.js';
import { GraphTooltip } from './GraphTooltip.js';
import { GraphEdgeTooltip } from './GraphEdgeTooltip.js';
import { GraphDetailPanel } from './GraphDetailPanel.js';
import { GraphLegend } from './GraphLegend.js';
import { Loader2, AlertCircle } from 'lucide-react';

export interface LivingNodalMapProps {
  mode?: 'global' | 'contextual';
  projectId?: string;
  activeSpace?: 'personal' | 'shared';
  onNavigate?: (view: string, projectId?: string) => void;
  onBack?: () => void;
  className?: string;
}

/**
 * Calculates Euclidean distance from point (px, py) to line segment (x1, y1)-(x2, y2).
 */
function distToSegment(
  px: number,
  py: number,
  x1: number,
  y1: number,
  x2: number,
  y2: number
): number {
  const l2 = (x2 - x1) ** 2 + (y2 - y1) ** 2;
  if (l2 === 0) return Math.hypot(px - x1, py - y1);
  let t = ((px - x1) * (x2 - x1) + (py - y1) * (y2 - y1)) / l2;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(px - (x1 + t * (x2 - x1)), py - (y1 + t * (y2 - y1)));
}

/**
 * Helper to draw a rounded rectangle on a 2D canvas context.
 */
function drawRoundedRect(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  width: number,
  height: number,
  radius: number
) {
  const r = Math.min(radius, width / 2, height / 2);
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + width - r, y);
  ctx.arcTo(x + width, y, x + width, y + r, r);
  ctx.lineTo(x + width, y + height - r);
  ctx.arcTo(x + width, y + height, x + width - r, y + height, r);
  ctx.lineTo(x + r, y + height);
  ctx.arcTo(x, y + height, x, y + height - r, r);
  ctx.lineTo(x, y + r);
  ctx.arcTo(x, y, x + r, y, r);
  ctx.closePath();
}

export const LivingNodalMap: React.FC<LivingNodalMapProps> = ({
  mode = 'global',
  projectId,
  activeSpace,
  onNavigate,
  className = '',
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const minimapRef = useRef<HTMLCanvasElement>(null);

  // Data states
  const [nodes, setNodes] = useState<GraphNode[]>([]);
  const [edges, setEdges] = useState<GraphEdge[]>([]);
  const [clusters, setClusters] = useState<CommunityCluster[]>([]);
  const [modularity, setModularity] = useState<number>(0);
  const [categories, setCategories] = useState<Array<{ id: string; name: string; color: string }>>([]);
  const [allTagsList, setAllTagsList] = useState<Array<{ id: string; name: string }>>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  // Viewport transformation state
  const [pan, setPan] = useState<{ x: number; y: number }>({ x: 0, y: 0 });
  const [zoom, setZoom] = useState<number>(1.0);

  // Filter & visual toggles
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [selectedCategoryId, setSelectedCategoryId] = useState<string | null>(null);
  const [selectedTag, setSelectedTag] = useState<string | null>(null);
  const [isBreathingActive, setIsBreathingActive] = useState<boolean>(true);
  const [showClusters, setShowClusters] = useState<boolean>(true);
  const [showGhostNodes, setShowGhostNodes] = useState<boolean>(true);

  // Interaction states
  const [hoveredNodeId, setHoveredNodeId] = useState<string | null>(null);
  const [hoveredEdgeId, setHoveredEdgeId] = useState<string | null>(null);
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  const [tooltipPos, setTooltipPos] = useState<{ x: number; y: number }>({ x: 0, y: 0 });
  const [containerSize, setContainerSize] = useState<{ width: number; height: number }>({
    width: 800,
    height: 600,
  });

  // Mutable refs for high-frequency 60 FPS animation loop
  const simNodesRef = useRef<PhysicsSimulationNode[]>([]);
  const simEdgesRef = useRef<Array<{ source: string; target: string; similarity: number; weight: number }>>([]);
  const animFrameIdRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(performance.now());
  const isDraggingRef = useRef<boolean>(false);
  const draggedNodeIdRef = useRef<string | null>(null);
  const dragStartPosRef = useRef<{ x: number; y: number }>({ x: 0, y: 0 });
  const panStartRef = useRef<{ x: number; y: number }>({ x: 0, y: 0 });
  const hasMovedRef = useRef<boolean>(false);
  const latestRenderPosMapRef = useRef<Map<string, { x: number; y: number; r: number }>>(new Map());

  // Dynamic min/max degree
  const degreeStats = useMemo(() => {
    if (nodes.length === 0) return { min: 0, max: 1 };
    const degs = nodes.map((n) => n.degree || 0);
    return {
      min: Math.min(...degs),
      max: Math.max(1, ...degs),
    };
  }, [nodes]);

  // Derive cluster thematic labels (e.g. "Musique", "Business", "Visuel")
  const clusterThemes = useMemo(() => {
    const map = new Map<number, { label: string; color: string }>();

    for (const cluster of clusters) {
      const clusterNodes = nodes.filter((n) => cluster.nodeIds.includes(n.id));
      if (clusterNodes.length === 0) continue;

      // Count category frequencies
      const catCounts = new Map<string, number>();
      const tagCounts = new Map<string, number>();

      for (const n of clusterNodes) {
        if (n.categoryName) {
          catCounts.set(n.categoryName, (catCounts.get(n.categoryName) || 0) + 1);
        }
        if (Array.isArray(n.tags)) {
          for (const t of n.tags) {
            const tName = typeof t === 'string' ? t : (t as any).name;
            if (tName) {
              tagCounts.set(tName, (tagCounts.get(tName) || 0) + 1);
            }
          }
        }
      }

      // Pick top category or top tag
      let topLabel = cluster.label;
      if (!topLabel) {
        let maxCount = 0;
        for (const [catName, count] of catCounts.entries()) {
          if (count > maxCount) {
            maxCount = count;
            topLabel = catName;
          }
        }
        if (!topLabel) {
          let maxTagCount = 0;
          for (const [tagName, count] of tagCounts.entries()) {
            if (count > maxTagCount) {
              maxTagCount = count;
              topLabel = `#${tagName}`;
            }
          }
        }
      }

      map.set(cluster.id, {
        label: topLabel || `Groupe thématique ${cluster.id + 1}`,
        color: cluster.color,
      });
    }

    return map;
  }, [clusters, nodes]);

  // 1. Fetch Graph Data & Categories & Tags
  const fetchGraphData = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      // Fetch taxonomy categories and tags for toolbar dropdowns
      Promise.all([
        categoriesApi.list().catch(() => ({ categories: [] })),
        tagsApi.list().catch(() => ({ tags: [] })),
      ]).then(([catsRes, tagsRes]) => {
        if (catsRes?.categories) setCategories(catsRes.categories);
        if (tagsRes?.tags) setAllTagsList(tagsRes.tags);
      });

      if (mode === 'contextual' && projectId) {
        const data: ContextualGraphData = await graphApi.getContextualGraph(projectId);
        setNodes(data.nodes || []);
        setEdges(data.edges || []);
        setClusters(data.clusters || []);
        setModularity(data.modularity || 0);
      } else {
        const data: GlobalGraphData = await graphApi.getGlobalGraph({ space: activeSpace });
        setNodes(data.nodes || []);
        setEdges(data.edges || []);
        setClusters(data.clusters || []);
        setModularity(data.modularity || 0);
      }
    } catch (err: any) {
      console.error('Failed to load graph data:', err);
      setError(err?.message || 'Failed to load graph data');
    } finally {
      setLoading(false);
    }
  }, [mode, projectId, activeSpace]);

  useEffect(() => {
    fetchGraphData();
  }, [fetchGraphData]);

  // 2. Initialize Physics Simulation Nodes & Edges on Data Change
  useEffect(() => {
    if (nodes.length === 0) return;

    const width = containerSize.width || 800;
    const height = containerSize.height || 600;
    const centerX = width / 2;
    const centerY = height / 2;

    const simNodes: PhysicsSimulationNode[] = nodes.map((n) => ({
      id: n.id,
      x: n.x ?? 0,
      y: n.y ?? 0,
      vx: 0,
      vy: 0,
      degree: n.degree || 0,
      community: n.community,
      pinned: (mode === 'contextual' && n.id === projectId) || n.pinned,
    }));

    initializeNodePositions(simNodes, centerX, centerY, mode === 'contextual' ? projectId : undefined);
    simNodesRef.current = simNodes;

    simEdgesRef.current = edges.map((e) => ({
      source: e.source,
      target: e.target,
      similarity: e.similarity || e.score || 0.5,
      weight: e.weight || e.score || 1.0,
    }));
  }, [nodes, edges, containerSize, mode, projectId]);

  // 3. Resize Observer
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const handleResize = () => {
      const rect = container.getBoundingClientRect();
      if (rect.width > 0 && rect.height > 0) {
        setContainerSize({ width: rect.width, height: rect.height });
      }
    };

    handleResize();
    if (typeof ResizeObserver !== 'undefined') {
      const observer = new ResizeObserver(handleResize);
      observer.observe(container);
      return () => observer.disconnect();
    }
  }, []);

  // 4. Hover & Filter Maps
  const filteredNodeIds = useMemo(() => {
    const query = searchQuery.trim().toLowerCase();
    const tagQuery = selectedTag ? selectedTag.toLowerCase().replace(/^#/, '') : null;

    return new Set(
      nodes
        .filter((n) => {
          if (mode === 'contextual' && !showGhostNodes && n.isGhost) return false;
          if (selectedCategoryId && n.categoryId !== selectedCategoryId) return false;
          if (tagQuery && !n.tags?.some((t) => t.toLowerCase() === tagQuery)) return false;
          if (query) {
            const matchTitle = n.title.toLowerCase().includes(query);
            const matchTag = n.tags?.some((t) => t.toLowerCase().includes(query));
            const matchCategory = n.categoryName?.toLowerCase().includes(query);
            if (!matchTitle && !matchTag && !matchCategory) return false;
          }
          return true;
        })
        .map((n) => n.id)
    );
  }, [nodes, searchQuery, selectedCategoryId, selectedTag, showGhostNodes, mode]);

  const neighborNodeIds = useMemo(() => {
    const focusId = hoveredNodeId || selectedNodeId;
    if (!focusId) return new Set<string>();
    const neighbors = new Set<string>([focusId]);
    for (const e of edges) {
      if (e.source === focusId) neighbors.add(e.target);
      if (e.target === focusId) neighbors.add(e.source);
    }
    return neighbors;
  }, [hoveredNodeId, selectedNodeId, edges]);

  // 5. 60 FPS HTML5 Canvas Animation & Render Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let isRunning = true;

    const render = () => {
      if (!isRunning) return;

      const dpr = window.devicePixelRatio || 1;
      const width = containerSize.width;
      const height = containerSize.height;

      if (canvas.width !== width * dpr || canvas.height !== height * dpr) {
        canvas.width = width * dpr;
        canvas.height = height * dpr;
      }

      ctx.save();
      ctx.scale(dpr, dpr);
      ctx.clearRect(0, 0, width, height);

      const themeBg = getComputedStyle(document.documentElement).getPropertyValue('--bg-primary').trim() || '#09090e';

      // Step physics simulation
      const centerX = width / 2;
      const centerY = height / 2;
      const simNodes = simNodesRef.current;
      const simEdges = simEdgesRef.current;

      simulateForceDirectedStep(simNodes, simEdges, {
        centerX,
        centerY,
        damping: 0.85,
        maxVelocity: 15.0,
      });

      // Calculate organic breathing positions
      const timeSec = isBreathingActive ? (performance.now() - startTimeRef.current) / 1000 : 0;
      const renderPosMap = new Map<string, { x: number; y: number; r: number }>();

      for (const sn of simNodes) {
        const offset = computeOrganicBreathingOffset(
          sn.id,
          { x: sn.x, y: sn.y },
          timeSec,
          sn.degree,
          degreeStats.min,
          degreeStats.max
        );
        renderPosMap.set(sn.id, offset);
      }

      latestRenderPosMapRef.current = renderPosMap;

      // Apply Affine Transform (Pan & Zoom)
      ctx.save();
      ctx.translate(pan.x, pan.y);
      ctx.scale(zoom, zoom);

      // -------------------------------------------------------------
      // Pass 1: Constellation Nebula Hulls & Centroid Text Labels (Removed for minimalism)

      // -------------------------------------------------------------
      // Pass 2: Graph Edges (Constellation Links)
      // -------------------------------------------------------------
      for (const edge of edges) {
        const p1 = renderPosMap.get(edge.source);
        const p2 = renderPosMap.get(edge.target);
        if (!p1 || !p2) continue;

        const isSourceVisible = filteredNodeIds.has(edge.source);
        const isTargetVisible = filteredNodeIds.has(edge.target);
        if (!isSourceVisible || !isTargetVisible) continue;

        const isEdgeHovered = hoveredEdgeId === edge.id;
        const isIncidentToHover =
          hoveredNodeId !== null && (edge.source === hoveredNodeId || edge.target === hoveredNodeId);
        const isIncidentToSelect =
          selectedNodeId !== null && (edge.source === selectedNodeId || edge.target === selectedNodeId);
        const isDimmed =
          (hoveredNodeId !== null || selectedNodeId !== null) &&
          !isIncidentToHover &&
          !isIncidentToSelect &&
          !isEdgeHovered;

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);

        if (isEdgeHovered) {
          ctx.strokeStyle = '#818cf8';
          ctx.lineWidth = 2.0 / zoom;
        } else if (isIncidentToHover || isIncidentToSelect) {
          ctx.strokeStyle = 'rgba(129, 140, 248, 0.45)';
          ctx.lineWidth = 1.2 / zoom;
        } else if (isDimmed) {
          ctx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
          ctx.lineWidth = 0.6 / zoom;
        } else {
          const sim = edge.similarity || edge.score || 0.5;
          const reasonLower = (edge.reason || '').toLowerCase();
          const hasSharedTags = Boolean(edge.sharedTags && edge.sharedTags.length > 0) || reasonLower.includes('tag');
          const isKeywordOrThematic =
            reasonLower.includes('keyword') ||
            reasonLower.includes('thematic') ||
            reasonLower.includes('overlap') ||
            reasonLower.includes('content');

          let strokeBase = '113, 113, 122'; // Zinc gray (#71717a)
          if (hasSharedTags) {
            strokeBase = '129, 140, 248'; // Indigo (#818cf8)
          } else if (isKeywordOrThematic) {
            strokeBase = '161, 161, 170'; // Muted zinc (#a1a1aa)
          }

          const alpha = 0.12 + 0.25 * Math.max(0, Math.min(1, sim));
          ctx.strokeStyle = `rgba(${strokeBase}, ${alpha})`;
          ctx.lineWidth = (1.0 + 1.2 * sim) / zoom;
        }

        ctx.stroke();
        ctx.restore();
      }

      // -------------------------------------------------------------
      // Pass 3 & 4: Node Body, Halo & Category Rings
      // -------------------------------------------------------------
      for (const node of nodes) {
        if (!filteredNodeIds.has(node.id)) continue;

        const p = renderPosMap.get(node.id);
        if (!p) continue;

        const isHovered = node.id === hoveredNodeId;
        const isSelected = node.id === selectedNodeId;
        const isNeighbor = neighborNodeIds.has(node.id);
        const isDimmed = (hoveredNodeId !== null || selectedNodeId !== null) && !isNeighbor;
        const isFocal = mode === 'contextual' && node.id === projectId;

        const baseRadius = p.r;
        const radius = isHovered || isSelected ? baseRadius * 1.25 : baseRadius;
        const alpha = node.isGhost ? (isHovered || isSelected ? 0.8 : 0.4) : isDimmed ? 0.2 : 1.0;

        ctx.save();
        ctx.globalAlpha = alpha;

        const accentColor = isFocal || isSelected
          ? '#ffffff'
          : node.clusterColor || node.categoryColor || '#a1a1aa';

        // Hollow Node Core (Flat & Minimal)
        ctx.beginPath();
        ctx.arc(p.x, p.y, radius, 0, Math.PI * 2);
        ctx.fillStyle = isHovered || isSelected || isFocal ? accentColor : themeBg;
        ctx.fill();
        ctx.strokeStyle = accentColor;
        ctx.lineWidth = 1.5 / zoom;
        ctx.stroke();

        // Highlight Outer Ring if selected/hovered (no glow, pure flat line)
        if (isHovered || isSelected || isFocal) {
          ctx.beginPath();
          ctx.arc(p.x, p.y, radius + 4 / zoom, 0, Math.PI * 2);
          ctx.strokeStyle = isSelected || isFocal ? '#ffffff' : 'rgba(255, 255, 255, 0.4)';
          ctx.lineWidth = 1.5 / zoom;
          ctx.stroke();
        }

        // -------------------------------------------------------------
        // Pass 5: High-Contrast Readable Node Typography with Pill Backing
        // -------------------------------------------------------------
        if (zoom >= 0.35 || node.degree >= 3 || isFocal || isHovered || isSelected) {
          const fontSize = 11;
          ctx.font = `500 ${fontSize}px "Inter", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif`;
          ctx.textAlign = 'center';
          ctx.textBaseline = 'top';

          const displayTitle = node.title.length > 24 ? node.title.slice(0, 22) + '…' : node.title;
          const textY = p.y + radius + 5;

          // Render text with thin dark outline for contrast without boxy pill clutter
          ctx.strokeStyle = '#0f0f15';
          ctx.lineWidth = 2.5;
          ctx.strokeText(displayTitle, p.x, textY);

          ctx.fillStyle = isHovered ? '#818cf8' : isSelected ? '#ffffff' : 'rgba(255, 255, 255, 0.65)';
          ctx.fillText(displayTitle, p.x, textY);
        }

        ctx.restore();
      }

      ctx.restore(); // Restore Affine Transform

      // Pass 6: Render Minimap in bottom-right
      renderMinimap(renderPosMap, width, height);

      ctx.restore(); // Restore DPR scale
      animFrameIdRef.current = requestAnimationFrame(render);
    };

    animFrameIdRef.current = requestAnimationFrame(render);

    return () => {
      isRunning = false;
      if (animFrameIdRef.current) {
        cancelAnimationFrame(animFrameIdRef.current);
      }
    };
  }, [
    nodes,
    edges,
    clusters,
    containerSize,
    pan,
    zoom,
    isBreathingActive,
    showClusters,
    hoveredNodeId,
    hoveredEdgeId,
    selectedNodeId,
    filteredNodeIds,
    neighborNodeIds,
    clusterThemes,
    degreeStats,
    mode,
    projectId,
  ]);

  // 6. Interactive Minimap Renderer
  const renderMinimap = (
    posMap: Map<string, { x: number; y: number; r: number }>,
    canvasWidth: number,
    canvasHeight: number
  ) => {
    const minimapCanvas = minimapRef.current;
    if (!minimapCanvas) return;

    const mCtx = minimapCanvas.getContext('2d');
    if (!mCtx) return;

    const mW = minimapCanvas.width;
    const mH = minimapCanvas.height;

    mCtx.clearRect(0, 0, mW, mH);

    // Compute bounding box in world space
    let minX = Infinity;
    let maxX = -Infinity;
    let minY = Infinity;
    let maxY = -Infinity;

    for (const p of posMap.values()) {
      if (p.x < minX) minX = p.x;
      if (p.x > maxX) maxX = p.x;
      if (p.y < minY) minY = p.y;
      if (p.y > maxY) maxY = p.y;
    }

    if (!isFinite(minX)) {
      minX = 0;
      maxX = canvasWidth;
      minY = 0;
      maxY = Math.max(100, canvasHeight);
    }

    const padding = 80;
    minX -= padding;
    maxX += padding;
    minY -= padding;
    maxY += padding;

    const worldW = maxX - minX || 1;
    const worldH = maxY - minY || 1;

    const scale = Math.min(mW / worldW, mH / worldH);
    const offX = (mW - worldW * scale) / 2;
    const offY = (mH - worldH * scale) / 2;

    // Draw mini nodes
    for (const [nid, p] of posMap.entries()) {
      if (!filteredNodeIds.has(nid)) continue;
      const mx = offX + (p.x - minX) * scale;
      const my = offY + (p.y - minY) * scale;

      mCtx.beginPath();
      mCtx.arc(mx, my, 2.5, 0, Math.PI * 2);
      mCtx.fillStyle =
        nid === hoveredNodeId || nid === selectedNodeId ? '#00F0FF' : 'rgba(255, 255, 255, 0.45)';
      mCtx.fill();
    }

    // Draw viewport frustum rect
    const vpTopLeft = affineTransformScreenToWorld({ x: 0, y: 0 }, pan, zoom);
    const vpBottomRight = affineTransformScreenToWorld({ x: canvasWidth, y: canvasHeight }, pan, zoom);

    const vx = offX + (vpTopLeft.x - minX) * scale;
    const vy = offY + (vpTopLeft.y - minY) * scale;
    const vw = (vpBottomRight.x - vpTopLeft.x) * scale;
    const vh = (vpBottomRight.y - vpTopLeft.y) * scale;

    mCtx.strokeStyle = 'rgba(99, 102, 241, 0.7)';
    mCtx.lineWidth = 1.5;
    mCtx.strokeRect(vx, vy, vw, vh);
  };

  // 7. Hit-Testing for Nodes & Edges
  const getNodeAtScreenPos = (screenX: number, screenY: number): GraphNode | null => {
    const worldPos = affineTransformScreenToWorld({ x: screenX, y: screenY }, pan, zoom);
    const timeSec = isBreathingActive ? (performance.now() - startTimeRef.current) / 1000 : 0;

    for (let i = nodes.length - 1; i >= 0; i--) {
      const node = nodes[i];
      if (!filteredNodeIds.has(node.id)) continue;

      const sn = simNodesRef.current.find((s) => s.id === node.id);
      if (!sn) continue;

      const offset = computeOrganicBreathingOffset(
        sn.id,
        { x: sn.x, y: sn.y },
        timeSec,
        sn.degree,
        degreeStats.min,
        degreeStats.max
      );

      const dist = Math.hypot(worldPos.x - offset.x, worldPos.y - offset.y);
      if (dist <= offset.r + 8 / zoom) {
        return node;
      }
    }

    return null;
  };

  const getEdgeAtScreenPos = (
    screenX: number,
    screenY: number,
    threshold: number = 8
  ): GraphEdge | null => {
    const posMap = latestRenderPosMapRef.current;
    if (posMap.size === 0) return null;

    for (const edge of edges) {
      const p1 = posMap.get(edge.source);
      const p2 = posMap.get(edge.target);
      if (!p1 || !p2) continue;

      if (!filteredNodeIds.has(edge.source) || !filteredNodeIds.has(edge.target)) continue;

      const s1 = affineTransformWorldToScreen(p1, pan, zoom);
      const s2 = affineTransformWorldToScreen(p2, pan, zoom);

      const dist = distToSegment(screenX, screenY, s1.x, s1.y, s2.x, s2.y);
      if (dist <= threshold) {
        return edge;
      }
    }

    return null;
  };

  // 8. Event Handlers: Mouse Pan / Zoom / Drag & Click Selection
  const handleMouseDown = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const rect = canvasRef.current?.getBoundingClientRect();
    if (!rect) return;

    const screenX = e.clientX - rect.left;
    const screenY = e.clientY - rect.top;

    hasMovedRef.current = false;
    isDraggingRef.current = true;
    dragStartPosRef.current = { x: screenX, y: screenY };
    panStartRef.current = { ...pan };

    const hitNode = getNodeAtScreenPos(screenX, screenY);
    if (hitNode) {
      draggedNodeIdRef.current = hitNode.id;
      const sn = simNodesRef.current.find((s) => s.id === hitNode.id);
      if (sn) {
        sn.pinned = true;
        sn.vx = 0;
        sn.vy = 0;
      }
    } else {
      draggedNodeIdRef.current = null;
    }
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const rect = canvasRef.current?.getBoundingClientRect();
    if (!rect) return;

    const screenX = e.clientX - rect.left;
    const screenY = e.clientY - rect.top;

    if (isDraggingRef.current) {
      const dx = screenX - dragStartPosRef.current.x;
      const dy = screenY - dragStartPosRef.current.y;

      if (Math.hypot(dx, dy) > 3) {
        hasMovedRef.current = true;
      }

      if (draggedNodeIdRef.current) {
        // Dragging single node
        const worldPos = affineTransformScreenToWorld({ x: screenX, y: screenY }, pan, zoom);
        const sn = simNodesRef.current.find((s) => s.id === draggedNodeIdRef.current);
        if (sn) {
          sn.x = worldPos.x;
          sn.y = worldPos.y;
          sn.vx = 0;
          sn.vy = 0;
        }
      } else {
        // Panning viewport
        setPan({
          x: panStartRef.current.x + dx,
          y: panStartRef.current.y + dy,
        });
      }
    } else {
      // Hover detection: Check node first, then edge
      const hitNode = getNodeAtScreenPos(screenX, screenY);
      if (hitNode) {
        setHoveredNodeId(hitNode.id);
        setHoveredEdgeId(null);
        setTooltipPos({ x: screenX, y: screenY });
      } else {
        setHoveredNodeId(null);
        const hitEdge = getEdgeAtScreenPos(screenX, screenY);
        if (hitEdge) {
          setHoveredEdgeId(hitEdge.id);
          setTooltipPos({ x: screenX, y: screenY });
        } else {
          setHoveredEdgeId(null);
        }
      }
    }
  };

  const handleMouseUp = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const rect = canvasRef.current?.getBoundingClientRect();
    if (!rect) return;

    const screenX = e.clientX - rect.left;
    const screenY = e.clientY - rect.top;

    if (!hasMovedRef.current && isDraggingRef.current) {
      // Direct click without drag: select node and open detail drawer panel
      const hitNode = getNodeAtScreenPos(screenX, screenY);
      if (hitNode) {
        setSelectedNodeId(hitNode.id);
      } else {
        // Click on background closes detail panel
        setSelectedNodeId(null);
      }
    }

    isDraggingRef.current = false;
    draggedNodeIdRef.current = null;
  };

  // Mobile Touch Gestures (Pan, Drag, Tap)
  const handleTouchStart = (e: React.TouchEvent<HTMLCanvasElement>) => {
    if (e.touches.length === 1) {
      const touch = e.touches[0];
      const rect = canvasRef.current?.getBoundingClientRect();
      if (!rect) return;

      const screenX = touch.clientX - rect.left;
      const screenY = touch.clientY - rect.top;

      hasMovedRef.current = false;
      isDraggingRef.current = true;
      dragStartPosRef.current = { x: screenX, y: screenY };
      panStartRef.current = { ...pan };

      const hitNode = getNodeAtScreenPos(screenX, screenY);
      if (hitNode) {
        draggedNodeIdRef.current = hitNode.id;
        const sn = simNodesRef.current.find((s) => s.id === hitNode.id);
        if (sn) {
          sn.pinned = true;
          sn.vx = 0;
          sn.vy = 0;
        }
      } else {
        draggedNodeIdRef.current = null;
      }
    }
  };

  const handleTouchMove = (e: React.TouchEvent<HTMLCanvasElement>) => {
    if (e.touches.length === 1 && isDraggingRef.current) {
      const touch = e.touches[0];
      const rect = canvasRef.current?.getBoundingClientRect();
      if (!rect) return;

      const screenX = touch.clientX - rect.left;
      const screenY = touch.clientY - rect.top;

      const dx = screenX - dragStartPosRef.current.x;
      const dy = screenY - dragStartPosRef.current.y;

      if (Math.hypot(dx, dy) > 4) {
        hasMovedRef.current = true;
      }

      if (draggedNodeIdRef.current) {
        const worldPos = affineTransformScreenToWorld({ x: screenX, y: screenY }, pan, zoom);
        const sn = simNodesRef.current.find((s) => s.id === draggedNodeIdRef.current);
        if (sn) {
          sn.x = worldPos.x;
          sn.y = worldPos.y;
          sn.vx = 0;
          sn.vy = 0;
        }
      } else {
        setPan({
          x: panStartRef.current.x + dx,
          y: panStartRef.current.y + dy,
        });
      }
    }
  };

  const handleTouchEnd = (e: React.TouchEvent<HTMLCanvasElement>) => {
    if (!hasMovedRef.current && isDraggingRef.current && e.changedTouches.length === 1) {
      const touch = e.changedTouches[0];
      const rect = canvasRef.current?.getBoundingClientRect();
      if (rect) {
        const screenX = touch.clientX - rect.left;
        const screenY = touch.clientY - rect.top;
        const hitNode = getNodeAtScreenPos(screenX, screenY);
        if (hitNode) {
          setSelectedNodeId(hitNode.id);
        } else {
          setSelectedNodeId(null);
        }
      }
    }

    isDraggingRef.current = false;
    draggedNodeIdRef.current = null;
  };

  const handleWheel = (e: React.WheelEvent<HTMLCanvasElement>) => {
    e.preventDefault();
    const rect = canvasRef.current?.getBoundingClientRect();
    if (!rect) return;

    const screenX = e.clientX - rect.left;
    const screenY = e.clientY - rect.top;

    const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
    const newZoom = Math.min(3.0, Math.max(0.1, zoom * zoomFactor));

    if (Math.abs(newZoom - zoom) > 1e-4) {
      // Cursor-invariant zoom pan delta
      const newPanX = screenX / newZoom - (screenX / zoom - pan.x);
      const newPanY = screenY / newZoom - (screenY / zoom - pan.y);

      setZoom(newZoom);
      setPan({ x: newPanX, y: newPanY });
    }
  };

  const handleNavigateToProject = (targetProjectId: string) => {
    if (onNavigate) {
      onNavigate('editor', targetProjectId);
    }
  };

  // Zoom HUD actions
  const handleZoomIn = () => {
    const newZoom = Math.min(3.0, zoom * 1.25);
    const centerX = containerSize.width / 2;
    const centerY = containerSize.height / 2;
    const newPanX = centerX / newZoom - (centerX / zoom - pan.x);
    const newPanY = centerY / newZoom - (centerY / zoom - pan.y);
    setZoom(newZoom);
    setPan({ x: newPanX, y: newPanY });
  };

  const handleZoomOut = () => {
    const newZoom = Math.max(0.1, zoom / 1.25);
    const centerX = containerSize.width / 2;
    const centerY = containerSize.height / 2;
    const newPanX = centerX / newZoom - (centerX / zoom - pan.x);
    const newPanY = centerY / newZoom - (centerY / zoom - pan.y);
    setZoom(newZoom);
    setPan({ x: newPanX, y: newPanY });
  };

  const handleResetView = () => {
    setZoom(1.0);
    setPan({ x: 0, y: 0 });
  };

  const hoveredNode = useMemo(() => {
    return nodes.find((n) => n.id === hoveredNodeId) || null;
  }, [nodes, hoveredNodeId]);

  const hoveredEdge = useMemo(() => {
    return edges.find((e) => e.id === hoveredEdgeId) || null;
  }, [edges, hoveredEdgeId]);

  const selectedNode = useMemo(() => {
    return nodes.find((n) => n.id === selectedNodeId) || null;
  }, [nodes, selectedNodeId]);

  return (
    <div
      ref={containerRef}
      className={`relative w-full h-full min-h-[500px] overflow-hidden select-none bg-transparent ${className}`}
      data-testid="living-nodal-map"
    >
      {/* HUD Toolbar with Category & Tag Filters */}
      <GraphToolbar
        mode={mode}
        searchQuery={searchQuery}
        onSearchChange={setSearchQuery}
        selectedCategoryId={selectedCategoryId}
        onSelectCategory={setSelectedCategoryId}
        categories={categories}
        selectedTag={selectedTag}
        onSelectTag={setSelectedTag}
        tags={allTagsList}
        isBreathingActive={isBreathingActive}
        onToggleBreathing={() => setIsBreathingActive((prev) => !prev)}
        showClusters={showClusters}
        onToggleClusters={() => setShowClusters((prev) => !prev)}
        showGhostNodes={showGhostNodes}
        onToggleGhostNodes={() => setShowGhostNodes((prev) => !prev)}
        onResetView={handleResetView}
        onZoomIn={handleZoomIn}
        onZoomOut={handleZoomOut}
        nodeCount={nodes.length}
        edgeCount={edges.length}
        modularity={modularity}
        zoomPercentage={Math.round(zoom * 100)}
      />

      {/* Loading & Error States */}
      {loading && (
        <div className="absolute inset-0 z-30 flex items-center justify-center bg-background">
          <div className="flex flex-col items-center gap-3">
            <Loader2 className="w-8 h-8 animate-spin text-accent" />
            <p className="text-sm font-medium text-foreground-muted">Chargement de la carte...</p>
          </div>
        </div>
      )}

      {error && !loading && (
        <div className="absolute inset-0 z-30 flex items-center justify-center bg-background">
          <div className="flex flex-col items-center gap-3 max-w-sm text-center p-6 bg-background-elevated border border-border rounded-xl">
            <AlertCircle className="w-8 h-8 text-destructive" />
            <h3 className="text-sm font-semibold text-foreground">Failed to load Nodal Map</h3>
            <p className="text-xs text-foreground-muted">{error}</p>
            <button
              onClick={fetchGraphData}
              className="mt-2 py-1.5 px-4 rounded-lg text-xs font-medium bg-accent hover:bg-accent-hover text-white transition-colors cursor-pointer"
            >
              Retry
            </button>
          </div>
        </div>
      )}

      {/* Main HTML5 Canvas */}
      <canvas
        ref={canvasRef}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        onWheel={handleWheel}
        className="w-full h-full block cursor-grab active:cursor-grabbing"
      />

      {/* Hover Inspection Tooltip for Nodes */}
      {hoveredNode && !selectedNode && !isDraggingRef.current && (
        <GraphTooltip
          node={hoveredNode}
          screenX={tooltipPos.x}
          screenY={tooltipPos.y}
          containerWidth={containerSize.width}
          containerHeight={containerSize.height}
          onOpenProject={handleNavigateToProject}
        />
      )}

      {/* Hover Inspection Tooltip for Edges */}
      {hoveredEdge && !hoveredNode && !selectedNode && !isDraggingRef.current && (
        <GraphEdgeTooltip
          edge={hoveredEdge}
          sourceNode={nodes.find((n) => n.id === hoveredEdge.source)}
          targetNode={nodes.find((n) => n.id === hoveredEdge.target)}
          screenX={tooltipPos.x}
          screenY={tooltipPos.y}
          containerWidth={containerSize.width}
          containerHeight={containerSize.height}
        />
      )}

      {/* Node Detail Drawer Panel (on click) */}
      {selectedNode && (
        <GraphDetailPanel
          node={selectedNode}
          allNodes={nodes}
          allEdges={edges}
          onClose={() => setSelectedNodeId(null)}
          onSelectNode={(neighborId) => setSelectedNodeId(neighborId)}
          onOpenProject={handleNavigateToProject}
        />
      )}

      {/* Connection & Centrality Legend */}
      <GraphLegend />

      {/* Interactive Minimap */}
      <div className="absolute bottom-4 right-4 z-20 hidden sm:block bg-background-surface border border-border rounded-xl p-1 shadow-md pointer-events-auto">
        <canvas
          ref={minimapRef}
          width={140}
          height={100}
          className="rounded-lg bg-background-elevated/80 block"
        />
      </div>
    </div>
  );
};

export default LivingNodalMap;
