/**
 * Graph Node Detail Drawer Panel
 * La Grande Bibliothèque — Milestone 4 (Feature R4)
 * 
 * Right-hand slide-out drawer displaying full project details, metadata,
 * and comprehensive connection lists with natural-language reasons.
 */

import React from 'react';
import type { GraphNode, GraphEdge } from '../../types/graph.js';
import {
  X,
  ExternalLink,
  Tag,
  Lock,
  Globe2,
  Layers,
  Network,
  ArrowRight,
  Zap,
  Calendar,
  User,
} from 'lucide-react';
import { cn } from '../../lib/utils.js';

export interface GraphDetailPanelProps {
  node: GraphNode | null;
  allNodes: GraphNode[];
  allEdges: GraphEdge[];
  onClose: () => void;
  onSelectNode: (nodeId: string) => void;
  onOpenProject: (projectId: string) => void;
}

export const GraphDetailPanel: React.FC<GraphDetailPanelProps> = ({
  node,
  allNodes,
  allEdges,
  onClose,
  onSelectNode,
  onOpenProject,
}) => {
  if (!node) return null;

  // Find all edges connected to this node
  const connectedEdges = allEdges.filter(
    (e) => e.source === node.id || e.target === node.id
  );

  // Map each edge to neighbor node details
  const connections = connectedEdges.map((edge) => {
    const neighborId = edge.source === node.id ? edge.target : edge.source;
    const neighbor = allNodes.find((n) => n.id === neighborId);
    return {
      edge,
      neighborId,
      neighbor,
      similarity: edge.similarity || edge.score || 0.5,
      reason: edge.reason || 'Shared thematic metadata and tags',
      sharedTags: edge.sharedTags || [],
    };
  });

  // Sort connections by highest similarity score
  connections.sort((a, b) => b.similarity - a.similarity);

  return (
    <aside
      className="absolute right-0 top-0 bottom-0 z-40 w-full sm:w-96 bg-background-surface border-l border-border shadow-lg flex flex-col animate-in slide-in-from-right duration-200 overflow-hidden"
      data-testid="graph-detail-panel"
      aria-label="Node Details"
    >
      {/* Header */}
      <div className="p-4 sm:p-5 border-b border-border bg-background-elevated flex items-start justify-between gap-3">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1.5 flex-wrap">
            {/* Space Badge */}
            {node.space === 'personal' ? (
              <span className="inline-flex items-center gap-1 text-[11px] font-medium px-2 py-0.5 rounded-md bg-indigo-500/10 text-indigo-400 border border-indigo-500/20">
                <Lock className="w-3 h-3" />
                Personnel
              </span>
            ) : (
              <span className="inline-flex items-center gap-1 text-[11px] font-medium px-2 py-0.5 rounded-md bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                <Globe2 className="w-3 h-3" />
                Partagé
              </span>
            )}

            {/* Category Badge */}
            {node.categoryName && (
              <span
                className="inline-flex items-center gap-1 text-[11px] font-medium px-2 py-0.5 rounded-md text-white shadow-2xs"
                style={{ backgroundColor: node.categoryColor || '#6366f1' }}
              >
                <Layers className="w-3 h-3" />
                {node.categoryName}
              </span>
            )}

            {/* Cluster Badge */}
            <span
              className="inline-flex items-center text-[10px] font-mono px-2 py-0.5 rounded-md"
              style={{
                backgroundColor: `${node.clusterColor}20`,
                color: node.clusterColor,
                border: `1px solid ${node.clusterColor}40`,
              }}
            >
              Groupe {node.community + 1}
            </span>
          </div>

          <h2 className="text-lg font-bold text-foreground leading-snug break-words">
            {node.title}
          </h2>
        </div>

        {/* Close Button (Touch target >= 44px) */}
        <button
          type="button"
          onClick={onClose}
          className="w-11 h-11 min-h-[44px] min-w-[44px] flex items-center justify-center p-2 text-foreground-muted hover:text-foreground hover:bg-background-hover rounded-xl cursor-pointer transition-colors shrink-0"
          aria-label="Close detail panel"
          data-testid="close-graph-detail-panel"
        >
          <X className="w-5 h-5" />
        </button>
      </div>

      {/* Body Content */}
      <div className="flex-1 overflow-y-auto p-4 sm:p-5 space-y-5">
        {/* Primary Action Button (Airy Design: >= 44px touch height, 16px text) */}
        <button
          type="button"
          onClick={() => onOpenProject(node.id)}
          className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-xl text-base font-semibold bg-accent hover:bg-accent-hover text-white shadow-md transition-all cursor-pointer min-h-[48px]"
          data-testid="open-project-editor-btn"
        >
          <span>Ouvrir dans l'éditeur</span>
          <ExternalLink className="w-4 h-4" />
        </button>

        {/* Description */}
        {node.description && (
          <div>
            <h4 className="text-xs font-mono font-semibold uppercase tracking-wider text-foreground-subtle mb-1.5">
              Description
            </h4>
            <p className="text-sm text-foreground-muted leading-relaxed bg-background-elevated/40 p-3 rounded-xl border border-border/50">
              {node.description}
            </p>
          </div>
        )}

        {/* Tags */}
        {node.tags && node.tags.length > 0 && (
          <div>
            <h4 className="text-xs font-mono font-semibold uppercase tracking-wider text-foreground-subtle mb-1.5 flex items-center gap-1">
              <Tag className="w-3 h-3 text-accent" />
              Tags ({node.tags.length})
            </h4>
            <div className="flex flex-wrap gap-1.5">
              {node.tags.map((tag) => (
                <span
                  key={tag}
                  className="inline-flex items-center gap-1 text-xs font-mono px-2.5 py-1 rounded-lg bg-background-elevated border border-border text-foreground-muted"
                >
                  #{tag}
                </span>
              ))}
            </div>
          </div>
        )}

        {/* Metadata Grid */}
        <div className="grid grid-cols-2 gap-2 text-xs pt-2 border-t border-border/60">
          <div className="bg-background-elevated/30 p-2.5 rounded-lg border border-border/40">
            <span className="text-foreground-subtle flex items-center gap-1 mb-0.5">
              <Network className="w-3 h-3 text-accent" /> Connexions
            </span>
            <span className="font-mono font-semibold text-foreground">
              {node.degree} liens
            </span>
          </div>

          <div className="bg-background-elevated/30 p-2.5 rounded-lg border border-border/40">
            <span className="text-foreground-subtle flex items-center gap-1 mb-0.5">
              <User className="w-3 h-3 text-accent" /> Propriétaire
            </span>
            <span className="font-medium text-foreground truncate block">
              {node.ownerName || 'Membre collectif'}
            </span>
          </div>
        </div>

        {/* Connections List with Verbatim Reasons */}
        <div className="pt-3 border-t border-border/60">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-xs font-mono font-semibold uppercase tracking-wider text-foreground-subtle flex items-center gap-1.5">
              <Network className="w-3.5 h-3.5 text-accent" />
              Projets connectés ({connections.length})
            </h3>
            <span className="text-[11px] text-foreground-subtle">Classés par similarité</span>
          </div>

          {connections.length === 0 ? (
            <div className="p-4 text-center bg-background-elevated/30 rounded-xl border border-border/40 text-xs text-foreground-muted">
              Aucune connexion directe établie pour ce projet.
            </div>
          ) : (
            <div className="space-y-2.5" data-testid="connected-projects-list">
              {connections.map(({ edge, neighborId, neighbor, similarity, reason, sharedTags }) => {
                const neighborTitle = neighbor?.title || neighborId;
                const matchPct = Math.round(similarity * 100);

                return (
                  <div
                    key={edge.id}
                    className="p-3.5 rounded-xl bg-background-elevated/50 hover:bg-background-elevated border border-border/80 transition-all flex flex-col gap-2 group"
                    data-testid={`connection-card-${neighborId}`}
                  >
                    {/* Neighbor Header */}
                    <div className="flex items-start justify-between gap-2">
                      <button
                        type="button"
                        onClick={() => onSelectNode(neighborId)}
                        className="text-left font-semibold text-sm text-foreground hover:text-accent transition-colors truncate flex-1 cursor-pointer"
                        title={`Select ${neighborTitle}`}
                      >
                        {neighborTitle}
                      </button>

                      <span className="inline-flex items-center gap-0.5 text-[10px] font-mono font-semibold px-2 py-0.5 rounded-full bg-cyan-500/15 text-cyan-400 border border-cyan-500/30 shrink-0 border-border">
                        <Zap className="w-2.5 h-2.5" />
                        {matchPct}% de correspondance
                      </span>
                    </div>

                    {/* Explanatory Reason */}
                    <div className="bg-background-surface/80 p-2.5 rounded-lg border border-border/60">
                      <div className="text-[10px] font-mono uppercase tracking-wider text-foreground-subtle mb-0.5">
                        Raison
                      </div>
                      <p className="text-xs text-foreground-muted leading-relaxed font-medium">
                        {reason}
                      </p>
                    </div>

                    {/* Shared Tags & Quick Jump */}
                    <div className="flex items-center justify-between gap-2 pt-1">
                      {sharedTags.length > 0 ? (
                        <div className="flex flex-wrap gap-1">
                          {sharedTags.slice(0, 3).map((t, idx) => (
                            <span
                              key={idx}
                              className="text-[10px] font-mono px-1.5 py-0.2 rounded bg-accent/10 text-accent"
                            >
                              #{t}
                            </span>
                          ))}
                        </div>
                      ) : (
                        <div />
                      )}

                      <div className="flex items-center gap-1.5 shrink-0">
                        <button
                          type="button"
                          onClick={() => onSelectNode(neighborId)}
                          className="w-9 h-9 min-h-[36px] min-w-[36px] flex items-center justify-center rounded-xl text-xs text-foreground-muted hover:text-foreground hover:bg-background-hover transition-colors cursor-pointer"
                          title="Centrer dans le graphe"
                        >
                          <Network className="w-4 h-4" />
                        </button>
                        <button
                          type="button"
                          onClick={() => onOpenProject(neighborId)}
                          className="w-9 h-9 min-h-[36px] min-w-[36px] flex items-center justify-center rounded-xl text-xs text-accent hover:bg-accent/15 transition-colors cursor-pointer"
                          title="Ouvrir le projet"
                        >
                          <ExternalLink className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    </aside>
  );
};

export default GraphDetailPanel;
